import { createSignal, createMemo, For, Show } from "solid-js";
import TaskItem from "./TaskItem";

export type Task = {
  id: number;
  title: string;
  done: boolean;
};

export default function App() {
  const [tasks, setTasks] = createSignal<Task[]>([]);
  const [text, setText] = createSignal("");
  let nextId = 1;

  const pending = createMemo(() => tasks().filter((t) => !t.done).length);

  const addTask = () => {
    const title = text().trim();
    if (!title) return;
    setTasks((prev) => [...prev, { id: nextId++, title, done: false }]);
    setText("");
  };

  const toggleTask = (id: number) => {
    setTasks((prev) =>
      prev.map((t) => (t.id === id ? { ...t, done: !t.done } : t))
    );
  };

  const deleteTask = (id: number) => {
    setTasks((prev) => prev.filter((t) => t.id !== id));
  };

  return (
    <div class="min-h-screen bg-gray-100 flex items-start justify-center p-6">
      <div class="w-full max-w-md bg-white rounded-lg shadow p-5">
        <h1 class="text-2xl font-bold mb-4 text-gray-800">Lista de tareas</h1>

        <div class="flex gap-2 mb-4">
          <input
            type="text"
            class="flex-1 border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-400"
            placeholder="¿Qué hay que hacer?"
            value={text()}
            onInput={(e) => setText(e.currentTarget.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") addTask();
            }}
          />
          <button
            class="bg-blue-500 hover:bg-blue-600 text-white rounded px-4 py-2"
            onClick={addTask}
          >
            Agregar
          </button>
        </div>

        <ul class="divide-y divide-gray-200">
          <For each={tasks()}>
            {(task) => (
              <TaskItem
                task={task}
                onToggle={() => toggleTask(task.id)}
                onDelete={() => deleteTask(task.id)}
              />
            )}
          </For>
        </ul>

        <p class="mt-4 text-sm text-gray-500">
          <Show when={tasks().length > 0} fallback={"No hay tareas"}>
            {pending()} pendientes
          </Show>
        </p>
      </div>
    </div>
  );
}

