model Product {
  id: ID
  name: String
  price: Number
}

model CartItem {
  id: ID
  name: String
  price: Number
  qty: Number
}

page Shop "/" {
  meta title="Carrito de compras"

  state products: Product[] = [
    { id: "1", name: "Remera", price: 19.99 },
    { id: "2", name: "Pantalón", price: 49.5 },
    { id: "3", name: "Zapatillas", price: 89 }
  ]
  state cart: CartItem[] = []

  computed total = cart.reduce((sum, i) => sum + i.price * i.qty, 0)
  computed totalText = total.toFixed(2)

  fn add(p) {
    let found = cart.find(i => i.id == p.id)
    if found {
      found.qty++
    } else {
      cart.push({ id: p.id, name: p.name, price: p.price, qty: 1 })
    }
  }

  fn inc(item) {
    item.qty++
  }

  fn dec(item) {
    if item.qty <= 1 {
      cart = cart.filter(i => i.id != item.id)
    } else {
      item.qty--
    }
  }

  column gap=6 pad=6 {
    title "Tienda"
    card pad=4 gap=3 {
      text "Productos" bold
      for p in products key p.id {
        row gap=4 align=center justify=between {
          text `${p.name} - $${p.price.toFixed(2)}`
          button "Agregar" primary -> add(p)
        }
      }
    }
    card pad=4 gap=3 {
      text "Carrito" bold
      if cart.length == 0 {
        text "El carrito está vacío" muted
      } else {
        for item in cart key item.id {
          row gap=4 align=center justify=between {
            text `${item.name} - $${(item.price * item.qty).toFixed(2)}`
            row gap=2 align=center {
              button "-" small -> dec(item)
              text `${item.qty}`
              button "+" small -> inc(item)
            }
          }
        }
      }
      divider
      text `Total: $${totalText}` bold large
    }
  }
}

