import { useState } from "react";

type TabId = "perfil" | "ajustes" | "ayuda";

interface Tab {
  id: TabId;
  label: string;
  content: string;
}

const tabs: Tab[] = [
  {
    id: "perfil",
    label: "Perfil",
    content:
      "Acá podés ver y editar tu información personal: nombre, foto, correo electrónico y datos de contacto.",
  },
  {
    id: "ajustes",
    label: "Ajustes",
    content:
      "Configurá las preferencias de la aplicación: notificaciones, idioma, privacidad y apariencia.",
  },
  {
    id: "ayuda",
    label: "Ayuda",
    content:
      "¿Necesitás una mano? Consultá las preguntas frecuentes o contactá con nuestro equipo de soporte.",
  },
];

