const contenido: Record<Tab, string> = {
  Perfil:
    "Acá podés ver y editar tu información personal, como tu nombre, tu foto y tu correo electrónico.",
  Ajustes:
    "Configurá las preferencias de la aplicación: notificaciones, idioma, tema y privacidad.",
  Ayuda:
    "¿Necesitás ayuda? Consultá las preguntas frecuentes o escribinos a soporte y te respondemos a la brevedad.",
};

export default function App() {
  const [activa, setActiva] = createSignal<Tab>("Perfil");

  return (
    <div class="min-h-screen bg-gray-100 flex items-start justify-center p-6">
      <div class="w-full max-w-xl bg-white rounded-xl shadow p-6">
        <div class="flex gap-2 border-b border-gray-200" role="tablist">
          <For each={tabs}>
            {(tab) => (
              <button
                type="button"
                role="tab"
                aria-selected={activa() === tab}
                onClick={() => setActiva(tab)}
                class="px-4 py-2 text-sm font-medium rounded-t-lg border-b-2 -mb-px transition-colors"
                classList={{
                  "border-blue-600 text-blue-600 bg-blue-50": activa() === tab,
                  "border-transparent text-gray-600 hover:text-gray-900 hover:bg-gray-50":
                    activa() !== tab,
                }}
              >
                {tab}
              </button>
            )}
          </For>
        </div>

        <div class="pt-6" role="tabpanel">
          <Show when={activa()}>
            <h2 class="text-lg font-semibold text-gray-800 mb-2">{activa()}</h2>
            <p class="text-gray-600">{contenido[activa()]}</p>
          </Show>
        </div>
      </div>
    </div>
  );
}

