type User = { id: string; name: string; email: string };

export default function App() {
  const [users, setUsers] = createSignal<User[]>([]);
  const [name, setName] = createSignal("");
  const [email, setEmail] = createSignal("");
  const [error, setError] = createSignal("");
  const [loading, setLoading] = createSignal(true);

  const load = async () => {
    try {
      const res = await fetch("/api/users");
      if (!res.ok) throw new Error();
      setUsers(await res.json());
    } catch {
      setError("Error al cargar usuarios");
    } finally {
      setLoading(false);
    }
  };

  onMount(load);

  const add = async () => {
    if (!email().includes("@")) {
      setError("Email inválido");
      return;
    }
    setError("");
    try {
      const res = await fetch("/api/users", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: name(), email: email() }),
      });
      if (!res.ok) {
        setError(res.status === 400 ? "Email inválido" : "Error al crear usuario");
        return;
      }
      const user: User = await res.json();
      setUsers((prev) => [...prev, user]);
      setName("");
      setEmail("");
    } catch {
      setError("Error al crear usuario");
    }
  };

  const remove = async (id: string) => {
    try {
      const res = await fetch(`/api/users/${encodeURIComponent(id)}`, {
        method: "DELETE",
      });
      if (!res.ok && res.status !== 404) throw new Error();
      setUsers((prev) => prev.filter((u) => u.id !== id));
    } catch {
      setError("Error al borrar usuario");
    }
  };

  return (
    <div class="max-w-xl mx-auto p-6">
      <h1 class="text-2xl font-bold mb-4">Usuarios</h1>
      <div class="flex gap-2 mb-2">
        <input
          class="border rounded px-2 py-1 flex-1"
          placeholder="Nombre"
          value={name()}
          onInput={(e) => setName(e.currentTarget.value)}
        />
        <input
          class="border rounded px-2 py-1 flex-1"
          placeholder="Email"
          value={email()}
          onInput={(e) => setEmail(e.currentTarget.value)}
        />
        <button
          class="bg-blue-600 text-white rounded px-3 py-1"
          onClick={add}
        >
          Agregar
        </button>
      </div>
      <Show when={error()}>
        <p class="text-red-600 mb-2">{error()}</p>
      </Show>
      <Show when={!loading()} fallback={<p>Cargando...</p>}>
        <ul class="divide-y">
          <For each={users()}>
            {(u) => (
              <li class="flex items-center justify-between py-2">
                <div>
                  <span class="font-semibold">{u.name}</span>{" "}
                  <span class="text-gray-600">{u.email}</span>
                </div>
                <button
                  class="bg-red-600 text-white rounded px-3 py-1"
                  onClick={() => remove(u.id)}
                >
                  Borrar
                </button>
              </li>
            )}
          </For>
        </ul>
      </Show>
    </div>
  );
}

