import { createServer } from "node:http";
import { randomUUID } from "node:crypto";

type User = { id: string; name: string; email: string };

const users: User[] = [];

const send = (res: import("node:http").ServerResponse, status: number, body?: unknown) => {
  if (body === undefined) {
    res.writeHead(status);
    res.end();
    return;
  }
  res.writeHead(status, { "Content-Type": "application/json" });
  res.end(JSON.stringify(body));
};

const readBody = (req: import("node:http").IncomingMessage): Promise<any> =>
  new Promise((resolve, reject) => {
    let data = "";
    req.on("data", (c) => (data += c));
    req.on("end", () => {
      try {
        resolve(data ? JSON.parse(data) : {});
      } catch (e) {
        reject(e);
      }
    });
    req.on("error", reject);
  });

const server = createServer(async (req, res) => {
  const url = new URL(req.url || "/", "http://localhost");
  const path = url.pathname;
  const method = req.method || "GET";

  try {
    if (path === "/api/users" && method === "GET") {
      return send(res, 200, users);
    }

    if (path === "/api/users" && method === "POST") {
      let body: any;
      try {
        body = await readBody(req);
      } catch {
        return send(res, 400, { error: "JSON inválido" });
      }
      const name = typeof body.name === "string" ? body.name.trim() : "";
      const email = typeof body.email === "string" ? body.email.trim() : "";
      if (!email.includes("@")) {
        return send(res, 400, { error: "Email inválido" });
      }
      const user: User = { id: randomUUID(), name, email };
      users.push(user);
      return send(res, 201, user);
    }

    const match = path.match(/^\/api\/users\/([^/]+)$/);
    if (match && method === "DELETE") {
      const id = decodeURIComponent(match[1]);
      const idx = users.findIndex((u) => u.id === id);
      if (idx === -1) return send(res, 404, { error: "No encontrado" });
      users.splice(idx, 1);
      return send(res, 204);
    }

    send(res, 404, { error: "No encontrado" });
  } catch {
    send(res, 500, { error: "Error interno" });
  }
});

server.listen(Number(process.env.PORT) || 3000);

import { createServer, IncomingMessage, ServerResponse } from "node:http";
import { randomUUID } from "node:crypto";

interface User {
  id: string;
  name: string;
  email: string;
}

const users: User[] = [];

function send(res: ServerResponse, status: number, body?: unknown) {
  if (body === undefined) {
    res.writeHead(status);
    res.end();
    return;
  }
  res.writeHead(status, { "Content-Type": "application/json; charset=utf-8" });
  res.end(JSON.stringify(body));
}

function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    let data = "";
    req.on("data", (chunk) => {
      data += chunk;
      if (data.length > 1e6) {
        reject(new Error("Body too large"));
        req.destroy();
      }
    });
    req.on("end", () => resolve(data));
    req.on("error", reject);
  });
}

const server = createServer(async (req, res) => {
  try {
    const url = new URL(req.url ?? "/", "http://localhost");
    const path = url.pathname.replace(/\/+$/, "") || "/";
    const method = req.method ?? "GET";

    if (path === "/api/users" && method === "GET") {
      return send(res, 200, users);
    }

    if (path === "/api/users" && method === "POST") {
      let parsed: any;
      try {
        parsed = JSON.parse(await readBody(req));
      } catch {
        return send(res, 400, { error: "JSON inválido" });
      }
      const name = typeof parsed?.name === "string" ? parsed.name.trim() : "";
      const email = typeof parsed?.email === "string" ? parsed.email.trim() : "";
      if (!email.includes("@")) {
        return send(res, 400, { error: "Email inválido" });
      }
      const user: User = { id: randomUUID(), name, email };
      users.push(user);
      return send(res, 201, user);
    }

    const match = path.match(/^\/api\/users\/([^/]+)$/);
    if (match && method === "DELETE") {
      const id = decodeURIComponent(match[1]);
      const idx = users.findIndex((u) => u.id === id);
      if (idx === -1) return send(res, 404, { error: "No encontrado" });
      users.splice(idx, 1);
      return send(res, 204);
    }

    send(res, 404, { error: "Not found" });
  } catch {
    send(res, 500, { error: "Error interno" });
  }
});

server.listen(Number(process.env.PORT) || 3000);

