import { createSignal, createMemo, onMount, For, Show } from "solid-js";

type Item = { id: number; name: string; bought: boolean };

export default function App() {
  const [items, setItems] = createSignal<Item[]>([]);
  const [text, setText] = createSignal("");
  const [error, setError] = createSignal("");
  const [loading, setLoading] = createSignal(true);

  const pending = createMemo(() => items().filter((i) => !i.bought).length);

  async function load() {
    try {
      const res = await fetch("/api/items");
      if (!res.ok) throw new Error();
      setItems(await res.json());
      setError("");
    } catch {
      setError("No se pudo cargar la lista");
    } finally {
      setLoading(false);
    }
  }

  onMount(load);

  async function add(e?: Event) {
    e?.preventDefault();
    const name = text().trim();
    if (!name) return;
    try {
      const res = await fetch("/api/items", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name }),
      });
      if (!res.ok) throw new Error();
      const item: Item = await res.json();
      setItems((prev) => [...prev, item]);
      setText("");
      setError("");
    } catch {
      setError("No se pudo agregar el ítem");
    }
  }

  async function buy(id: number) {
    try {
      const res = await fetch(`/api/items/${id}/bought`, { method: "POST" });
      if (!res.ok) throw new Error();
      const updated: Item = await res.json();
      setItems((prev) => prev.map((i) => (i.id === id ? updated : i)));
      setError("");
    } catch {
      setError("No se pudo marcar como comprado");
    }
  }

  async function remove(id: number) {
    try {
      const res = await fetch(`/api/items/${id}`, { method: "DELETE" });
      if (!res.ok && res.status !== 404) throw new Error();
      setItems((prev) => prev.filter((i) => i.id !== id));
      setError("");
    } catch {
      setError("No se pudo borrar el ítem");
    }
  }

  return (
    <div class="max-w-md mx-auto p-4">
      <h1 class="text-2xl font-bold mb-2">Lista de compras</h1>
      <p class="mb-4 text-gray-700">{pending()} por comprar</p>
      <form class="flex gap-2 mb-4" onSubmit={add}>
        <input
          class="flex-1 border rounded px-2 py-1"
          placeholder="Producto"
          value={text()}
          onInput={(e) => setText(e.currentTarget.value)}
        />
        <button type="submit" class="bg-blue-600 text-white rounded px-3 py-1">
          Agregar
        </button>
      </form>
      <Show when={error()}>
        <p class="text-red-600 mb-2">{error()}</p>
      </Show>
      <Show when={!loading()} fallback={<p>Cargando...</p>}>
        <ul class="space-y-2">
          <For each={items()}>
            {(item) => (
              <li class="flex items-center gap-2 border rounded px-2 py-1">
                <span class="flex-1">
                  {item.name}
                  <Show when={item.bought}>
                    <span class="text-green-600 ml-1">✓</span>
                  </Show>
                </span>
                <Show when={!item.bought}>
                  <button
                    class="bg-green-600 text-white rounded px-2 py-1"
                    onClick={() => buy(item.id)}
                  >
                    Comprado
                  </button>
                </Show>
                <button
                  class="bg-red-600 text-white rounded px-2 py-1"
                  onClick={() => remove(item.id)}
                >
                  Borrar
                </button>
              </li>
            )}
          </For>
        </ul>
      </Show>
    </div>
  );
}

