import { useCallback, useEffect, useState } from "react";

type Author = { id: number; name: string };
type Post = { id: number; title: string; authorId: number; authorName: string };

export default function App() {
  const [authors, setAuthors] = useState<Author[]>([]);
  const [posts, setPosts] = useState<Post[]>([]);
  const [authorName, setAuthorName] = useState("");
  const [title, setTitle] = useState("");
  const [selectedAuthor, setSelectedAuthor] = useState("");
  const [error, setError] = useState("");

  const load = useCallback(async () => {
    try {
      const [a, p] = await Promise.all([
        fetch("/api/authors").then((r) => r.json()),
        fetch("/api/posts").then((r) => r.json()),
      ]);
      setAuthors(a);
      setPosts(p);
    } catch {
      setError("Error de conexión");
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  useEffect(() => {
    if (authors.length === 0) {
      if (selectedAuthor !== "") setSelectedAuthor("");
    } else if (!authors.some((a) => String(a.id) === selectedAuthor)) {
      setSelectedAuthor(String(authors[0].id));
    }
  }, [authors, selectedAuthor]);

  const createAuthor = async () => {
    const name = authorName.trim();
    if (!name) return;
    setError("");
    const res = await fetch("/api/authors", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name }),
    });
    if (!res.ok) {
      setError("No se pudo crear el autor");
      return;
    }
    setAuthorName("");
    await load();
  };

  const deleteAuthor = async (id: number) => {
    setError("");
    const res = await fetch(`/api/authors/${id}`, { method: "DELETE" });
    if (!res.ok) {
      const data = await res.json().catch(() => ({}));
      setError(data.error || "Error al borrar");
    }
    await load();
  };

  const createPost = async () => {
    const t = title.trim();
    if (!t || !selectedAuthor) return;
    setError("");
    const res = await fetch("/api/posts", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title: t, authorId: Number(selectedAuthor) }),
    });
    if (!res.ok) {
      setError("No se pudo publicar");
      return;
    }
    setTitle("");
    await load();
  };

  return (
    <div className="mx-auto max-w-2xl space-y-6 p-6">
      <h1 className="text-3xl font-bold">Blog</h1>

      {error && (
        <div role="alert" className="rounded bg-red-100 p-2 text-red-700">
          {error}
        </div>
      )}

      <section className="space-y-2">
        <h2 className="text-xl font-semibold">Autores</h2>
        <div className="flex gap-2">
          <input
            className="flex-1 rounded border p-2"
            placeholder="Autor"
            value={authorName}
            onChange={(e) => setAuthorName(e.target.value)}
          />
          <button
            className="rounded bg-blue-600 px-4 py-2 text-white"
            onClick={createAuthor}
          >
            Crear autor
          </button>
        </div>
        <ul className="space-y-1">
          {authors.map((a) => (
            <li
              key={a.id}
              className="flex items-center justify-between rounded border p-2"
            >
              <span>{a.name}</span>
              <button
                className="rounded bg-red-600 px-3 py-1 text-white"
                onClick={() => deleteAuthor(a.id)}
              >
                Borrar autor
              </button>
            </li>
          ))}
        </ul>
      </section>

      <section className="space-y-2">
        <h2 className="text-xl font-semibold">Posts</h2>
        <div className="flex gap-2">
          <input
            className="flex-1 rounded border p-2"
            placeholder="Título"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
          />
          <select
            className="rounded border p-2"
            value={selectedAuthor}
            onChange={(e) => setSelectedAuthor(e.target.value)}
          >
            {authors.map((a) => (
              <option key={a.id} value={a.id}>
                {a.name}
              </option>
            ))}
          </select>
          <button
            className="rounded bg-green-600 px-4 py-2 text-white"
            onClick={createPost}
          >
            Publicar
          </button>
        </div>
        <ul className="space-y-2">
          {posts.map((p) => (
            <li key={p.id} className="rounded border p-3">
              <div className="font-semibold">{p.title}</div>
              <div className="text-sm text-gray-600">por {p.authorName}</div>
            </li>
          ))}
        </ul>
      </section>
    </div>
  );
}

