import { createServer, IncomingMessage, ServerResponse } from "node:http";

type Author = { id: number; name: string };
type Post = { id: number; title: string; authorId: number };

const authors: Author[] = [];
const posts: Post[] = [];
let nextAuthorId = 1;
let nextPostId = 1;

function send(res: ServerResponse, status: number, data: unknown) {
  res.writeHead(status, { "Content-Type": "application/json" });
  res.end(JSON.stringify(data));
}

function readBody(req: IncomingMessage): Promise<any> {
  return new Promise((resolve) => {
    let raw = "";
    req.on("data", (c) => (raw += c));
    req.on("end", () => {
      try {
        resolve(raw ? JSON.parse(raw) : {});
      } catch {
        resolve({});
      }
    });
    req.on("error", () => resolve({}));
  });
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url || "/", "http://localhost");
  const path = url.pathname.replace(/\/+$/, "") || "/";
  const method = req.method || "GET";

  if (!path.startsWith("/api/")) {
    return send(res, 404, { error: "No encontrado" });
  }

  if (path === "/api/authors" && method === "GET") {
    return send(res, 200, authors);
  }

  if (path === "/api/authors" && method === "POST") {
    const body = await readBody(req);
    const name = typeof body.name === "string" ? body.name.trim() : "";
    if (!name) return send(res, 400, { error: "Nombre requerido" });
    const author = { id: nextAuthorId++, name };
    authors.push(author);
    return send(res, 201, author);
  }

  const m = path.match(/^\/api\/authors\/(\d+)$/);
  if (m && method === "DELETE") {
    const id = Number(m[1]);
    const idx = authors.findIndex((a) => a.id === id);
    if (idx === -1) return send(res, 404, { error: "Autor no encontrado" });
    if (posts.some((p) => p.authorId === id)) {
      return send(res, 409, { error: "El autor tiene posts" });
    }
    authors.splice(idx, 1);
    return send(res, 200, { ok: true });
  }

  if (path === "/api/posts" && method === "GET") {
    const list = posts.map((p) => ({
      ...p,
      authorName: authors.find((a) => a.id === p.authorId)?.name ?? "",
    }));
    return send(res, 200, list);
  }

  if (path === "/api/posts" && method === "POST") {
    const body = await readBody(req);
    const title = typeof body.title === "string" ? body.title.trim() : "";
    const authorId = Number(body.authorId);
    if (!title) return send(res, 400, { error: "Título requerido" });
    if (!authors.some((a) => a.id === authorId)) {
      return send(res, 400, { error: "Autor inválido" });
    }
    const post = { id: nextPostId++, title, authorId };
    posts.push(post);
    return send(res, 201, post);
  }

  return send(res, 404, { error: "No encontrado" });
});

server.listen(Number(process.env.PORT) || 3000);

