import { createSignal, For, Show, onMount } from "solid-js";

interface Author {
  id: number;
  name: string;
}
interface Post {
  id: number;
  title: string;
  authorId: number;
  authorName: string;
}

export default function App() {
  const [authors, setAuthors] = createSignal<Author[]>([]);
  const [posts, setPosts] = createSignal<Post[]>([]);
  const [authorName, setAuthorName] = createSignal("");
  const [title, setTitle] = createSignal("");
  const [selected, setSelected] = createSignal("");
  const [errors, setErrors] = createSignal<Record<number, string>>({});

  const load = async () => {
    const [a, p] = await Promise.all([
      fetch("/api/authors").then((r) => r.json()),
      fetch("/api/posts").then((r) => r.json()),
    ]);
    setAuthors(a);
    setPosts(p);
    if (!a.some((x: Author) => String(x.id) === selected())) {
      setSelected(a.length ? String(a[0].id) : "");
    }
  };

  onMount(load);

  const createAuthor = async () => {
    const name = authorName().trim();
    if (!name) return;
    await fetch("/api/authors", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name }),
    });
    setAuthorName("");
    await load();
  };

  const createPost = async () => {
    const t = title().trim();
    if (!t || !selected()) return;
    await fetch("/api/posts", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title: t, authorId: Number(selected()) }),
    });
    setTitle("");
    await load();
  };

  const deleteAuthor = async (id: number) => {
    const res = await fetch(`/api/authors/${id}`, { method: "DELETE" });
    if (!res.ok) {
      let msg = "El autor tiene posts";
      try {
        const d = await res.json();
        if (d.error) msg = d.error;
      } catch {}
      setErrors({ ...errors(), [id]: msg });
      return;
    }
    setErrors((e) => {
      const { [id]: _, ...rest } = e;
      return rest;
    });
    await load();
  };

  return (
    <div class="max-w-2xl mx-auto p-6 space-y-8">
      <h1 class="text-3xl font-bold">Blog</h1>

      <section class="space-y-2">
        <h2 class="text-xl font-semibold">Autores</h2>
        <div class="flex gap-2">
          <input
            class="border rounded px-2 py-1 flex-1"
            placeholder="Autor"
            value={authorName()}
            onInput={(e) => setAuthorName(e.currentTarget.value)}
          />
          <button
            class="bg-blue-600 text-white rounded px-3 py-1"
            onClick={createAuthor}
          >
            Crear autor
          </button>
        </div>
        <ul class="space-y-1">
          <For each={authors()}>
            {(a) => (
              <li class="flex items-center gap-2">
                <span>{a.name}</span>
                <button
                  class="bg-red-600 text-white rounded px-2 py-0.5 text-sm"
                  onClick={() => deleteAuthor(a.id)}
                >
                  Borrar autor
                </button>
                <Show when={errors()[a.id]}>
                  <span class="text-red-600 text-sm">{errors()[a.id]}</span>
                </Show>
              </li>
            )}
          </For>
        </ul>
      </section>

      <section class="space-y-2">
        <h2 class="text-xl font-semibold">Nuevo post</h2>
        <div class="flex gap-2">
          <input
            class="border rounded px-2 py-1 flex-1"
            placeholder="Título"
            value={title()}
            onInput={(e) => setTitle(e.currentTarget.value)}
          />
          <select
            class="border rounded px-2 py-1"
            value={selected()}
            onChange={(e) => setSelected(e.currentTarget.value)}
          >
            <For each={authors()}>
              {(a) => (
                <option value={String(a.id)} selected={String(a.id) === selected()}>
                  {a.name}
                </option>
              )}
            </For>
          </select>
          <button
            class="bg-green-600 text-white rounded px-3 py-1"
            onClick={createPost}
          >
            Publicar
          </button>
        </div>
      </section>

      <section class="space-y-2">
        <h2 class="text-xl font-semibold">Posts</h2>
        <For each={posts()}>
          {(p) => (
            <article class="border rounded p-3">
              <h3 class="font-bold">{p.title}</h3>
              <p class="text-gray-600">por {p.authorName}</p>
            </article>
          )}
        </For>
      </section>
    </div>
  );
}

