import { useEffect, useState } from "react";

type Product = {
  id: number;
  name: string;
  code: string;
  price: number;
};

export default function App() {
  const [products, setProducts] = useState<Product[]>([]);
  const [name, setName] = useState("");
  const [code, setCode] = useState("");
  const [price, setPrice] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  const load = async () => {
    try {
      const res = await fetch("/api/products");
      if (res.ok) {
        const data: Product[] = await res.json();
        setProducts(data);
      }
    } catch {
      setError("Error de conexión");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, []);

  const save = async () => {
    setError("");
    setSaving(true);
    try {
      const res = await fetch("/api/products", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name, code, price }),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) {
        setError(data.error || "Error");
      } else {
        setProducts((p) => [...p, data as Product]);
        setName("");
        setCode("");
        setPrice("");
      }
    } catch {
      setError("Error de conexión");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-100 p-6">
      <div className="mx-auto max-w-md space-y-4">
        <h1 className="text-2xl font-bold text-gray-800">Productos</h1>
        <div className="space-y-2 rounded bg-white p-4 shadow">
          <input
            className="w-full rounded border p-2"
            placeholder="Nombre"
            value={name}
            onChange={(e) => setName(e.target.value)}
          />
          <input
            className="w-full rounded border p-2"
            placeholder="Código"
            value={code}
            onChange={(e) => setCode(e.target.value)}
          />
          <input
            className="w-full rounded border p-2"
            placeholder="Precio"
            value={price}
            onChange={(e) => setPrice(e.target.value)}
          />
          <button
            className="w-full rounded bg-blue-600 p-2 text-white hover:bg-blue-700 disabled:opacity-50"
            onClick={save}
            disabled={saving}
          >
            Guardar
          </button>
          {error && <p className="text-sm text-red-600">{error}</p>}
        </div>
        <ul className="space-y-2">
          {loading && <li className="text-gray-500">Cargando...</li>}
          {products.map((p) => (
            <li key={p.id} className="rounded bg-white p-3 shadow">
              <span className="font-semibold">{p.name}</span>{" "}
              <span className="text-gray-500">{p.code}</span>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

