import http from "node:http";

type Product = { id: number; name: string; code: string; price: number };

const products: Product[] = [];
let nextId = 1;

const send = (res: http.ServerResponse, status: number, body: unknown) => {
  res.writeHead(status, { "Content-Type": "application/json" });
  res.end(JSON.stringify(body));
};

const server = http.createServer((req, res) => {
  const url = (req.url || "").split("?")[0].replace(/\/+$/, "");

  if (url === "/api/products" && req.method === "GET") {
    return send(res, 200, products);
  }

  if (url === "/api/products" && req.method === "POST") {
    let raw = "";
    req.on("data", (c) => (raw += c));
    req.on("end", () => {
      let body: any;
      try {
        body = JSON.parse(raw || "{}");
      } catch {
        return send(res, 400, { error: "JSON inválido" });
      }
      const name = typeof body.name === "string" ? body.name.trim() : "";
      const code = typeof body.code === "string" ? body.code.trim() : "";
      const priceStr = String(body.price ?? "").trim().replace(",", ".");
      const price = priceStr === "" ? NaN : Number(priceStr);

      if (name.length < 3) return send(res, 400, { error: "Nombre muy corto" });
      if (!code) return send(res, 400, { error: "Código inválido" });
      if (products.some((p) => p.code === code))
        return send(res, 409, { error: "Código repetido" });
      if (!Number.isFinite(price) || price < 0)
        return send(res, 400, { error: "Precio inválido" });

      const product: Product = { id: nextId++, name, code, price };
      products.push(product);
      send(res, 201, product);
    });
    return;
  }

  send(res, 404, { error: "No encontrado" });
});

server.listen(Number(process.env.PORT) || 3000);

