      });
      const data = await res.json();
      if (!res.ok) {
        setError(data.error || "Error");
        return;
      }
      setProducts((p) => [...p, data as Product]);
      setName("");
      setCode("");
      setPrice("");
    } catch {
      setError("Error de conexión");
