import { createServer, IncomingMessage, ServerResponse } from "node:http";

interface Product {
  id: number;
  name: string;
  code: string;
  price: number;
}

const products: Product[] = [];
let nextId = 1;

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { "Content-Type": "application/json; charset=utf-8" });
  res.end(JSON.stringify(body));
}

function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    let data = "";
    req.on("data", (chunk) => {
      data += chunk;
      if (data.length > 1_000_000) {
        reject(new Error("Body too large"));
        req.destroy();
      }
    });
    req.on("end", () => resolve(data));
    req.on("error", reject);
  });
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url ?? "/", "http://localhost");
  const path = url.pathname.replace(/\/+$/, "") || "/";

  if (path === "/api/products" && req.method === "GET") {
    return send(res, 200, products);
  }

  if (path === "/api/products" && req.method === "POST") {
    let parsed: any;
    try {
      const raw = await readBody(req);
      parsed = raw ? JSON.parse(raw) : {};
    } catch {
      return send(res, 400, { error: "Solicitud inválida" });
    }

    const name = typeof parsed?.name === "string" ? parsed.name.trim() : "";
    const code = typeof parsed?.code === "string" ? parsed.code.trim() : "";
    const rawPrice = parsed?.price;
    const price =
      typeof rawPrice === "number"
        ? rawPrice
        : typeof rawPrice === "string" && rawPrice.trim() !== ""
          ? Number(rawPrice)
          : NaN;

    if (name.length < 3) {
      return send(res, 400, { error: "Nombre muy corto" });
    }
    if (products.some((p) => p.code === code)) {
      return send(res, 409, { error: "Código repetido" });
    }
    if (!Number.isFinite(price) || price < 0) {
      return send(res, 400, { error: "Precio inválido" });
    }

    const product: Product = { id: nextId++, name, code, price };
    products.push(product);
    return send(res, 201, product);
  }

  if (path.startsWith("/api/")) {
    return send(res, 404, { error: "No encontrado" });
  }

  send(res, 404, { error: "No encontrado" });
});

