import { useEffect, useRef, useState } from "react";

export default function App() {
  const [file, setFile] = useState<File | null>(null);
  const [photoUrl, setPhotoUrl] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const loadPhoto = async () => {
    try {
      const res = await fetch("/api/photo/info");
      if (!res.ok) throw new Error("No se pudo cargar la foto");
      const data: { exists: boolean; version: number } = await res.json();
      setPhotoUrl(data.exists ? `/api/photo?v=${data.version}` : null);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Error desconocido");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadPhoto();
  }, []);

  const handleUpload = async () => {
    if (!file) return;
    setUploading(true);
    setError(null);
    try {
      const res = await fetch("/api/photo", {
        method: "PUT",
        headers: { "Content-Type": file.type || "application/octet-stream" },
        body: file,
      });
      if (!res.ok) {
        const data = await res.json().catch(() => null);
        throw new Error(data?.error || "Error al subir la foto");
      }
      setFile(null);
      if (inputRef.current) inputRef.current.value = "";
      await loadPhoto();
    } catch (e) {
      setError(e instanceof Error ? e.message : "Error desconocido");
    } finally {
      setUploading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-100 flex items-start justify-center p-6">
      <div className="w-full max-w-md bg-white rounded-2xl shadow p-6 space-y-5">
        <h1 className="text-2xl font-bold text-gray-800">Mi perfil</h1>

        <div className="flex flex-col gap-3">
          <input
            ref={inputRef}
            type="file"
            accept="image/*"
            onChange={(e) => setFile(e.target.files?.[0] ?? null)}
            className="block w-full text-sm text-gray-600 file:mr-3 file:py-2 file:px-4 file:rounded-lg file:border-0 file:bg-indigo-50 file:text-indigo-700 hover:file:bg-indigo-100"
          />
          <button
            onClick={handleUpload}
            disabled={!file || uploading}
            className="bg-indigo-600 text-white rounded-lg py-2 font-medium disabled:opacity-50 disabled:cursor-not-allowed hover:bg-indigo-700 transition"
          >
            {uploading ? "Subiendo..." : "Subir"}
          </button>
        </div>

        {error && (
          <p className="text-sm text-red-600 bg-red-50 rounded-lg p-2">{error}</p>
        )}

        <div className="flex justify-center">
          {loading ? (
            <p className="text-gray-500">Cargando...</p>
          ) : photoUrl ? (
            <img
              src={photoUrl}
              alt="Foto de perfil"
              className="w-64 h-64 object-cover rounded-full border-4 border-indigo-100 shadow"
            />
          ) : (
            <p className="text-gray-500">Todavía no hay foto subida.</p>
          )}
        </div>
      </div>
    </div>
  );
}

