import http from "node:http";

const MAX_SIZE = 10 * 1024 * 1024;

let photo: { data: Buffer; type: string; version: number } | null = null;
let versionCounter = 0;

function sendJson(res: http.ServerResponse, status: number, body: unknown) {
  res.writeHead(status, { "Content-Type": "application/json" });
  res.end(JSON.stringify(body));
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url || "/", "http://localhost");
  const path = url.pathname;

  if (path === "/api/photo/info" && req.method === "GET") {
    return sendJson(res, 200, {
      exists: photo !== null,
      version: photo?.version ?? 0,
    });
  }

  if (path === "/api/photo" && req.method === "GET") {
    if (!photo) return sendJson(res, 404, { error: "No hay foto" });
    res.writeHead(200, {
      "Content-Type": photo.type,
      "Content-Length": photo.data.length,
      "Cache-Control": "no-cache",
    });
    return res.end(photo.data);
  }

  if (path === "/api/photo" && req.method === "PUT") {
    const type = String(req.headers["content-type"] || "");
    if (!type.startsWith("image/")) {
      req.resume();
      return sendJson(res, 400, { error: "El archivo debe ser una imagen" });
    }
    const chunks: Buffer[] = [];
    let size = 0;
    let aborted = false;
    req.on("data", (chunk: Buffer) => {
      if (aborted) return;
      size += chunk.length;
      if (size > MAX_SIZE) {
        aborted = true;
        sendJson(res, 413, { error: "La imagen supera los 10 MB" });
        req.resume();
        return;
      }
      chunks.push(chunk);
    });
    req.on("end", () => {
      if (aborted) return;
      if (size === 0) return sendJson(res, 400, { error: "Archivo vacío" });
      photo = { data: Buffer.concat(chunks), type, version: ++versionCounter };
      sendJson(res, 200, { ok: true, version: photo.version });
    });
    req.on("error", () => {
      if (!aborted) sendJson(res, 400, { error: "Error al leer la subida" });
    });
    return;
  }

  if (path.startsWith("/api/")) {
    return sendJson(res, 404, { error: "Ruta no encontrada" });
  }

  res.writeHead(404);
  res.end();
});

server.listen(Number(process.env.PORT) || 3000);

