import { createServer } from "node:http";
import type { IncomingMessage, ServerResponse } from "node:http";

const MAX_SIZE = 10 * 1024 * 1024;

let photo: { data: Buffer; type: string; version: number } | null = null;
let versionCounter = 0;

function json(res: ServerResponse, status: number, body: unknown) {
  res.writeHead(status, { "Content-Type": "application/json" });
  res.end(JSON.stringify(body));
}

function readBody(req: IncomingMessage): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    req.on("data", (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_SIZE) {
        reject(new Error("too_large"));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on("end", () => resolve(Buffer.concat(chunks)));
    req.on("error", reject);
  });
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url ?? "/", "http://localhost");
  const path = url.pathname;

  try {
    if (path === "/api/photo/info" && req.method === "GET") {
      return json(res, 200, {
        exists: photo !== null,
        version: photo?.version ?? 0,
      });
    }

    if (path === "/api/photo" && req.method === "GET") {
      if (!photo) return json(res, 404, { error: "No hay foto" });
      res.writeHead(200, {
        "Content-Type": photo.type,
        "Content-Length": photo.data.length,
        "Cache-Control": "no-cache",
      });
      return res.end(photo.data);
    }

    if (path === "/api/photo" && (req.method === "PUT" || req.method === "POST")) {
      const type = (req.headers["content-type"] ?? "").split(";")[0].trim();
      if (!type.startsWith("image/")) {
        return json(res, 400, { error: "El archivo debe ser una imagen." });
      }
      let data: Buffer;
      try {
        data = await readBody(req);
      } catch (e) {
        if (e instanceof Error && e.message === "too_large") {
          return json(res, 413, { error: "La imagen es demasiado grande (máx. 10 MB)." });
        }
        throw e;
      }
      if (data.length === 0) {
        return json(res, 400, { error: "Archivo vacío." });
      }
      versionCounter += 1;
      photo = { data, type, version: versionCounter };
      return json(res, 200, { ok: true, version: versionCounter });
    }

    json(res, 404, { error: "No encontrado" });
  } catch {
    json(res, 500, { error: "Error interno del servidor" });
  }
});

server.listen(Number(process.env.PORT) || 3000);

