import { createSignal, onMount, Show } from "solid-js";

export default function App() {
  const [file, setFile] = createSignal<File | null>(null);
  const [version, setVersion] = createSignal(0);
  const [exists, setExists] = createSignal(false);
  const [loading, setLoading] = createSignal(true);
  const [uploading, setUploading] = createSignal(false);
  const [error, setError] = createSignal("");

  onMount(async () => {
    try {
      const r = await fetch("/api/photo/info");
      const d = await r.json();
      setExists(d.exists);
      setVersion(d.version);
    } catch {
      setError("No se pudo cargar la foto");
    } finally {
      setLoading(false);
    }
  });

  const upload = async () => {
    const f = file();
    if (!f) {
      setError("Elegí una foto primero");
      return;
    }
    setError("");
    setUploading(true);
    try {
      const r = await fetch("/api/photo", {
        method: "POST",
        headers: { "Content-Type": f.type || "application/octet-stream" },
        body: f,
      });
      const d = await r.json();
      if (!r.ok) throw new Error(d.error || "Error al subir");
      setVersion(d.version);
      setExists(true);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Error al subir");
    } finally {
      setUploading(false);
    }
  };

  return (
    <div class="min-h-screen bg-gray-100 flex items-start justify-center p-6">
      <div class="bg-white rounded-xl shadow p-6 w-full max-w-md">
        <h1 class="text-2xl font-bold mb-4">Mi perfil</h1>
        <div class="flex items-center gap-2 mb-3">
          <input
            type="file"
            accept="image/*"
            class="flex-1 text-sm"
            onChange={(e) => setFile(e.currentTarget.files?.[0] ?? null)}
          />
          <button
            class="bg-blue-600 text-white px-4 py-2 rounded disabled:opacity-50"
            disabled={uploading() || !file()}
            onClick={upload}
          >
            {uploading() ? "Subiendo..." : "Subir"}
          </button>
        </div>
        <Show when={error()}>
          <p class="text-red-600 text-sm mb-3">{error()}</p>
        </Show>
        <Show when={!loading()} fallback={<p class="text-gray-500">Cargando...</p>}>
          <Show
            when={exists()}
            fallback={<p class="text-gray-500">Todavía no hay foto.</p>}
          >
            <img
              src={`/api/photo?v=${version()}`}
              alt="Foto de perfil"
              class="w-full rounded-lg object-cover"
            />
          </Show>
        </Show>
      </div>
    </div>
  );
}

