import React, { useEffect, useState, useCallback } from "react";

type Producto = { id: number; nombre: string };

const PRODUCTOS: Producto[] = [
  { id: 1, nombre: "Mesa" },
  { id: 2, nombre: "Silla" },
];

function useRuta() {
  const [path, setPath] = useState<string>(window.location.pathname);

  useEffect(() => {
    const onPop = () => setPath(window.location.pathname);
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, []);

  const navegar = useCallback((to: string) => {
    if (to !== window.location.pathname) {
      window.history.pushState({}, "", to);
    }
    setPath(to);
  }, []);

  return { path, navegar };
}

type LinkProps = {
  to: string;
  navegar: (to: string) => void;
  children: React.ReactNode;
  className?: string;
};

function Link({ to, navegar, children, className }: LinkProps) {
  const onClick = (e: React.MouseEvent<HTMLAnchorElement>) => {
    if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey || e.button !== 0) return;
    e.preventDefault();
    navegar(to);
  };
  return (
    <a href={to} onClick={onClick} className={className}>
      {children}
    </a>
  );
}

export default function App() {
  const { path, navegar } = useRuta();

  const normalizado =
    path.length > 1 && path.endsWith("/") ? path.slice(0, -1) : path;

  const linkClass = "text-blue-600 underline hover:text-blue-800";

  let contenido: React.ReactNode;

  const match = normalizado.match(/^\/productos\/(\d+)$/);
  const producto = match
    ? PRODUCTOS.find((p) => p.id === Number(match[1]))
    : undefined;

  if (normalizado === "/") {
    contenido = (
      <div>
        <h1 className="text-2xl font-bold mb-4">Productos</h1>
        <ul className="space-y-2">
          {PRODUCTOS.map((p) => (
            <li key={p.id} className="flex items-center gap-3">
              <span>{p.nombre}</span>
              <Link to={`/productos/${p.id}`} navegar={navegar} className={linkClass}>
                Ver
              </Link>
            </li>
          ))}
        </ul>
      </div>
    );
  } else if (producto) {
    contenido = (
      <div>
        <h1 className="text-2xl font-bold mb-4">{producto.nombre}</h1>
        <Link to="/" navegar={navegar} className={linkClass}>
          Volver
        </Link>
      </div>
    );
  } else {
    contenido = <h1 className="text-2xl font-bold">No encontrado</h1>;
  }

  return (
    <div className="min-h-screen bg-gray-50 p-8 text-gray-900">{contenido}</div>
  );
}

