import { createSignal, createMemo, onCleanup, For, Show, JSX } from "solid-js";

type Producto = { id: number; nombre: string };

const PRODUCTOS: Producto[] = [
  { id: 1, nombre: "Mesa" },
  { id: 2, nombre: "Silla" },
];

const [path, setPath] = createSignal(window.location.pathname);

function navegar(to: string) {
  if (to !== window.location.pathname) {
    window.history.pushState({}, "", to);
  }
  setPath(window.location.pathname);
}

function Link(props: { href: string; children: JSX.Element; class?: string }) {
  return (
    <a
      href={props.href}
      class={props.class}
      onClick={(e) => {
        if (
          e.defaultPrevented ||
          e.button !== 0 ||
          e.metaKey ||
          e.ctrlKey ||
          e.shiftKey ||
          e.altKey
        )
          return;
        e.preventDefault();
        navegar(props.href);
      }}
    >
      {props.children}
    </a>
  );
}

export default function App() {
  const onPop = () => setPath(window.location.pathname);
  window.addEventListener("popstate", onPop);
  onCleanup(() => window.removeEventListener("popstate", onPop));

  const ruta = createMemo(() => {
    const p = path().length > 1 ? path().replace(/\/+$/, "") : path();
    if (p === "/") return { tipo: "home" as const };
    const m = p.match(/^\/productos\/(\d+)$/);
    if (m) {
      const prod = PRODUCTOS.find((x) => x.id === Number(m[1]));
      if (prod) return { tipo: "detalle" as const, producto: prod };
    }
    return { tipo: "nada" as const };
  });

  const detalle = createMemo(() => {
    const r = ruta();
    return r.tipo === "detalle" ? r.producto : null;
  });

  return (
    <div class="max-w-md mx-auto p-6">
      <Show when={ruta().tipo === "home"}>
        <h1 class="text-2xl font-bold mb-4">Productos</h1>
        <ul class="space-y-2">
          <For each={PRODUCTOS}>
            {(p) => (
              <li class="flex items-center justify-between border rounded p-3">
                <span>{p.nombre}</span>
                <Link
                  href={`/productos/${p.id}`}
                  class="text-blue-600 underline"
                >
                  Ver
                </Link>
              </li>
            )}
          </For>
        </ul>
      </Show>

      <Show when={detalle()}>
        {(p) => (
          <div>
            <h1 class="text-2xl font-bold mb-4">{p().nombre}</h1>
            <Link href="/" class="text-blue-600 underline">
              Volver
            </Link>
          </div>
        )}
      </Show>

      <Show when={ruta().tipo === "nada"}>
        <h1 class="text-2xl font-bold">No encontrado</h1>
      </Show>
    </div>
  );
}

import { createSignal, createMemo, onCleanup, For, Show, JSX } from "solid-js";

type Product = { id: number; name: string };

const PRODUCTS: Product[] = [
  { id: 1, name: "Mesa" },
  { id: 2, name: "Silla" },
];

const [path, setPath] = createSignal(window.location.pathname);

function navigate(to: string) {
  if (to !== window.location.pathname) {
    window.history.pushState({}, "", to);
  }
  setPath(to);
}

function Link(props: { href: string; children: JSX.Element; class?: string }) {
  const onClick = (e: MouseEvent) => {
    if (
      e.defaultPrevented ||
      e.button !== 0 ||
      e.metaKey ||
      e.ctrlKey ||
      e.shiftKey ||
      e.altKey
    ) {
      return;
    }
    e.preventDefault();
    navigate(props.href);
  };
  return (
    <a
      href={props.href}
      onClick={onClick}
      class={props.class ?? "text-blue-600 underline hover:text-blue-800"}
    >
      {props.children}
    </a>
  );
}

type Route =
  | { type: "home" }
  | { type: "product"; product: Product }
  | { type: "notfound" };

export default function App() {
  const onPop = () => setPath(window.location.pathname);
  window.addEventListener("popstate", onPop);
  onCleanup(() => window.removeEventListener("popstate", onPop));

  const route = createMemo<Route>(() => {
    let p = path();
    if (p.length > 1 && p.endsWith("/")) p = p.slice(0, -1);
    if (p === "/" || p === "") return { type: "home" };
    const m = p.match(/^\/productos\/(\d+)$/);
    if (m) {
      const product = PRODUCTS.find((x) => x.id === Number(m[1]));
      if (product) return { type: "product", product };
    }
    return { type: "notfound" };
  });

  const product = () => {
    const r = route();
    return r.type === "product" ? r.product : null;
  };

  return (
    <div class="min-h-screen bg-gray-50 p-8 text-gray-800">
      <div class="mx-auto max-w-md rounded-lg bg-white p-6 shadow">
        <Show when={route().type === "home"}>
          <h1 class="mb-4 text-2xl font-bold">Productos</h1>
          <ul class="space-y-2">
            <For each={PRODUCTS}>
              {(p) => (
                <li class="flex items-center justify-between border-b py-2">
                  <span>{p.name}</span>
                  <Link href={`/productos/${p.id}`}>Ver</Link>
                </li>
              )}
            </For>
          </ul>
        </Show>

        <Show when={product()}>
          {(p) => (
            <div>
              <h1 class="mb-4 text-2xl font-bold">{p().name}</h1>
              <Link href="/">Volver</Link>
            </div>
          )}
        </Show>

        <Show when={route().type === "notfound"}>
          <h1 class="text-2xl font-bold">No encontrado</h1>
        </Show>
      </div>
    </div>
  );
}

