import { useMemo, useState } from "react";

type Empleado = { nombre: string; edad: number };

const EMPLEADOS: Empleado[] = [
  { nombre: "Caro", edad: 35 },
  { nombre: "Ana", edad: 30 },
  { nombre: "Dani", edad: 28 },
  { nombre: "Beto", edad: 25 },
];

type Orden = "ninguno" | "nombre" | "edad";

export default function App() {
  const [orden, setOrden] = useState<Orden>("ninguno");
  const [filtro, setFiltro] = useState("");

  const visibles = useMemo(() => {
    const texto = filtro.trim().toLowerCase();
    let lista = EMPLEADOS.filter((e) =>
      e.nombre.toLowerCase().includes(texto)
    );
    if (orden === "nombre") {
      lista = [...lista].sort((a, b) =>
        a.nombre.localeCompare(b.nombre, "es", { sensitivity: "base" })
      );
    } else if (orden === "edad") {
      lista = [...lista].sort((a, b) => a.edad - b.edad);
    }
    return lista;
  }, [orden, filtro]);

  return (
    <div className="min-h-screen bg-gray-100 p-6 flex justify-center">
      <div className="w-full max-w-md bg-white rounded-xl shadow p-6 space-y-4">
        <h1 className="text-xl font-bold text-gray-800">Empleados</h1>

        <div className="flex gap-2">
          <button
            onClick={() => setOrden("nombre")}
            className="px-3 py-2 rounded bg-blue-600 text-white text-sm hover:bg-blue-700"
          >
            Ordenar por nombre
          </button>
          <button
            onClick={() => setOrden("edad")}
            className="px-3 py-2 rounded bg-blue-600 text-white text-sm hover:bg-blue-700"
          >
            Ordenar por edad
          </button>
        </div>

        <input
          type="text"
          placeholder="Filtrar"
          value={filtro}
          onChange={(e) => setFiltro(e.target.value)}
          className="w-full border border-gray-300 rounded px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-400"
        />

        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="border-b-2 border-gray-300">
              <th className="py-2 px-2">Nombre</th>
              <th className="py-2 px-2">Edad</th>
            </tr>
          </thead>
          <tbody>
            {visibles.map((e) => (
              <tr key={e.nombre} className="border-b border-gray-200">
                <td className="py-2 px-2">{e.nombre}</td>
                <td className="py-2 px-2">{e.edad}</td>
              </tr>
            ))}
          </tbody>
        </table>

        <p className="text-sm text-gray-700">Empleados: {visibles.length}</p>
      </div>
    </div>
  );
}

