page Cronometro "/" {
  state n = 0
  state timer = null

  fn start() {
    if timer != null { return }
    timer = setInterval(() => { n++ }, 100)
  }

  fn pause() {
    if timer != null {
      clearInterval(timer)
      timer = null
    }
  }

  fn reset() {
    pause()
    n = 0
