import { useEffect, useRef, useState } from "react";

export default function App() {
  const [tiempo, setTiempo] = useState<number>(0);
  const [corriendo, setCorriendo] = useState<boolean>(false);
  const intervaloRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    if (!corriendo) return;
    intervaloRef.current = setInterval(() => {
      setTiempo((t) => t + 1);
    }, 100);
    return () => {
      if (intervaloRef.current !== null) {
        clearInterval(intervaloRef.current);
        intervaloRef.current = null;
      }
    };
  }, [corriendo]);

  const iniciar = () => setCorriendo(true);
  const pausar = () => setCorriendo(false);
  const reiniciar = () => {
    setCorriendo(false);
    setTiempo(0);
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-100">
      <div className="bg-white rounded-xl shadow-lg p-8 flex flex-col items-center gap-6">
        <h1 className="text-3xl font-bold text-gray-800">Tiempo: {tiempo}</h1>
        <div className="flex gap-3">
          <button
            onClick={iniciar}
            className="px-4 py-2 rounded-lg bg-green-600 text-white font-medium hover:bg-green-700 transition-colors"
          >
            Iniciar
          </button>
          <button
            onClick={pausar}
            className="px-4 py-2 rounded-lg bg-yellow-500 text-white font-medium hover:bg-yellow-600 transition-colors"
          >
            Pausar
          </button>
          <button
            onClick={reiniciar}
            className="px-4 py-2 rounded-lg bg-red-600 text-white font-medium hover:bg-red-700 transition-colors"
          >
            Reiniciar
          </button>
        </div>
      </div>
    </div>
  );
}

