import { useEffect, useState, type MouseEvent, type ReactNode } from "react";

function normalize(path: string): string {
  const p = path.replace(/\/+$/, "");
  return p === "" ? "/" : p;
}

function usePath(): string {
  const [path, setPath] = useState(() => normalize(window.location.pathname));
  useEffect(() => {
    const onChange = () => setPath(normalize(window.location.pathname));
    window.addEventListener("popstate", onChange);
    return () => window.removeEventListener("popstate", onChange);
  }, []);
  return path;
}

function navigate(to: string) {
  if (normalize(window.location.pathname) === normalize(to)) return;
  window.history.pushState({}, "", to);
  window.dispatchEvent(new PopStateEvent("popstate"));
}

function Link({
  to,
  children,
  className = "",
}: {
  to: string;
  children: ReactNode;
  className?: string;
}) {
  const onClick = (e: MouseEvent<HTMLAnchorElement>) => {
    if (
      e.defaultPrevented ||
      e.button !== 0 ||
      e.metaKey ||
      e.ctrlKey ||
      e.shiftKey ||
      e.altKey
    )
      return;
    e.preventDefault();
    navigate(to);
  };
  return (
    <a href={to} onClick={onClick} className={className}>
      {children}
    </a>
  );
}

function Menu() {
  const [likes, setLikes] = useState(0);
  return (
    <nav className="flex items-center gap-4 bg-gray-800 px-6 py-3 text-white">
      <Link to="/" className="hover:underline">
        Inicio
      </Link>
      <Link to="/equipo" className="hover:underline">
        Equipo
      </Link>
      <div className="ml-auto flex items-center gap-3">
        <button
          type="button"
          onClick={() => setLikes((n) => n + 1)}
          className="rounded bg-blue-500 px-3 py-1 hover:bg-blue-600"
        >
          Me gusta
        </button>
        <span>Likes: {likes}</span>
      </div>
    </nav>
  );
}

function Inicio() {
  return <h1 className="text-3xl font-bold">Bienvenido</h1>;
}

function Equipo() {
  return (
    <div>
      <h1 className="mb-4 text-3xl font-bold">Nuestro equipo</h1>
      <ul className="list-disc pl-6">
        <li>
          <Link to="/equipo/ana" className="text-blue-600 hover:underline">
            Ana
          </Link>
        </li>
        <li>
          <Link to="/equipo/beto" className="text-blue-600 hover:underline">
            Beto
          </Link>
        </li>
      </ul>
    </div>
  );
}

function Perfil({ nombre }: { nombre: string }) {
  let decoded = nombre;
  try {
    decoded = decodeURIComponent(nombre);
  } catch {
    /* keep raw */
  }
  const display = decoded.charAt(0).toUpperCase() + decoded.slice(1);
  return (
    <div>
      <h1 className="mb-4 text-3xl font-bold">Perfil de {display}</h1>
      <Link to="/equipo" className="text-blue-600 hover:underline">
        Volver al equipo
      </Link>
    </div>
  );
}

function NoEncontrada() {
  return <h1 className="text-3xl font-bold">Página no encontrada</h1>;
}

export default function App() {
  const path = usePath();

  let page: ReactNode;
  if (path === "/") {
    page = <Inicio />;
  } else if (path === "/equipo") {
    page = <Equipo />;
  } else if (/^\/equipo\/[^/]+$/.test(path)) {
    page = <Perfil nombre={path.split("/")[2]} />;
  } else {
    page = <NoEncontrada />;
  }

  return (
