            <Link to="/equipo/beto" navigate={navigate} className={linkClass}>
              Beto
            </Link>
          </li>
        </ul>
      </div>
    );
  } else if (segments[0] === "equipo" && segments.length === 2) {
    const nombre = capitalize(safeDecode(segments[1]));
    content = (
      <div>
        <h1 className="text-3xl font-bold mb-4">Perfil de {nombre}</h1>
        <Link to="/equipo" navigate={navigate} className={linkClass}>
          Volver al equipo
        </Link>
      </div>
    );
  } else {
    content = <h1 className="text-3xl font-bold">Página no encontrada</h1>;
  }

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900">
      <nav className="flex items-center gap-4 bg-white border-b border-gray-200 px-6 py-3 shadow-sm">
        <Link to="/" navigate={navigate} className={linkClass}>
          Inicio
        </Link>
        <Link to="/equipo" navigate={navigate} className={linkClass}>
          Equipo
        </Link>
        <div className="ml-auto flex items-center gap-3">
          <button
            type="button"
            onClick={() => setLikes((n) => n + 1)}
            className="rounded bg-blue-600 px-3 py-1 text-white hover:bg-blue-700"
          >
            Me gusta
          </button>
          <span>Likes: {likes}</span>
        </div>
      </nav>
      <main className="p-6">{content}</main>
    </div>
  );
}

