page Signup "/" {
  state step = 1
  state name = ""
  state plan = "Gratis"
  state news = false
  state error = ""
  state done = false

  fn next1() {
    if name.trim() == "" {
      error = "Nombre requerido"
      return
    }
    error = ""
    step = 2
  }

  fn back() {
    step--
  }

  fn toStep3() {
    step = 3
  }

  fn confirm() {
    done = true
  }

  column gap=4 pad=4 {
    if done {
      title `¡Listo, ${name}!`
    } else {
      text `Paso ${step} de 3` muted
