import { useState } from "react";

export default function App() {
  const [step, setStep] = useState<1 | 2 | 3>(1);
  const [nombre, setNombre] = useState("");
  const [plan, setPlan] = useState("Gratis");
  const [novedades, setNovedades] = useState(false);
  const [error, setError] = useState("");
  const [confirmado, setConfirmado] = useState(false);

  const btn =
    "px-4 py-2 rounded-lg font-medium transition-colors";
  const primary = `${btn} bg-indigo-600 text-white hover:bg-indigo-700`;
  const secondary = `${btn} bg-gray-200 text-gray-800 hover:bg-gray-300`;

  const siguientePaso1 = () => {
    if (nombre.trim() === "") {
      setError("Nombre requerido");
      return;
    }
    setError("");
    setStep(2);
  };

  if (confirmado) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-100 p-4">
        <div className="w-full max-w-sm bg-white rounded-xl shadow p-6">
          <h1 className="text-2xl font-bold text-center text-gray-900">
            ¡Listo, {nombre.trim()}!
          </h1>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-100 p-4">
      <div className="w-full max-w-sm bg-white rounded-xl shadow p-6 space-y-4">
        <h1 className="text-lg font-semibold text-gray-900">Paso {step} de 3</h1>

        {step === 1 && (
          <div className="space-y-4">
            <div>
              <input
                type="text"
                placeholder="Nombre"
                value={nombre}
                onChange={(e) => {
                  setNombre(e.target.value);
                  if (error) setError("");
                }}
                className="w-full border border-gray-300 rounded-lg px-3 py-2 focus:outline-none focus:ring-2 focus:ring-indigo-500"
              />
              {error && <p className="text-red-600 text-sm mt-1">{error}</p>}
            </div>
            <div className="flex justify-end">
              <button type="button" onClick={siguientePaso1} className={primary}>
                Siguiente
              </button>
            </div>
          </div>
        )}

        {step === 2 && (
          <div className="space-y-4">
            <select
              aria-label="Plan"
              value={plan}
              onChange={(e) => setPlan(e.target.value)}
              className="w-full border border-gray-300 rounded-lg px-3 py-2 bg-white"
            >
              <option value="Gratis">Gratis</option>
              <option value="Pro">Pro</option>
            </select>
            <label className="flex items-center gap-2 text-gray-800">
              <input
                type="checkbox"
                checked={novedades}
                onChange={(e) => setNovedades(e.target.checked)}
                className="h-4 w-4"
              />
              Recibir novedades
            </label>
            <div className="flex justify-between">
              <button type="button" onClick={() => setStep(1)} className={secondary}>
                Atrás
              </button>
              <button type="button" onClick={() => setStep(3)} className={primary}>
                Siguiente
              </button>
            </div>
          </div>
        )}

        {step === 3 && (
          <div className="space-y-4">
            <div className="space-y-1 text-gray-800">
              <p>
                {nombre.trim()} eligió {plan}
              </p>
              {novedades && <p>Con novedades</p>}
            </div>
            <div className="flex justify-between">
              <button type="button" onClick={() => setStep(2)} className={secondary}>
                Atrás
              </button>
              <button
                type="button"
                onClick={() => setConfirmado(true)}
                className={primary}
              >
                Confirmar
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

