import { useEffect, useState } from "react";

type Task = { id: number; title: string; done: boolean };

export default function App() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [text, setText] = useState("");
  const [filter, setFilter] = useState("todas");
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editText, setEditText] = useState("");
  const [error, setError] = useState("");

  const load = async () => {
    try {
      const res = await fetch("/api/tasks");
      if (!res.ok) throw new Error();
      setTasks(await res.json());
      setError("");
    } catch {
      setError("No se pudieron cargar las tareas");
    }
  };

  useEffect(() => {
    load();
  }, []);

  const add = async () => {
    const title = text.trim();
    if (!title) return;
    try {
      const res = await fetch("/api/tasks", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ title }),
      });
      if (!res.ok) throw new Error();
      const t: Task = await res.json();
      setTasks((prev) => [...prev, t]);
      setText("");
    } catch {
      setError("No se pudo crear la tarea");
    }
  };

  const update = async (id: number, patch: Partial<Task>) => {
    try {
      const res = await fetch(`/api/tasks/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(patch),
      });
      if (!res.ok) throw new Error();
      const t: Task = await res.json();
      setTasks((prev) => prev.map((x) => (x.id === id ? t : x)));
      return true;
    } catch {
      setError("No se pudo actualizar la tarea");
      return false;
    }
  };

  const save = async (id: number) => {
    const title = editText.trim();
    if (!title) return;
    if (await update(id, { title })) {
      setEditingId(null);
      setEditText("");
    }
  };

  const visible = tasks.filter((t) =>
    filter === "todas" ? true : filter === "pendientes" ? !t.done : t.done
  );

  return (
    <div className="mx-auto max-w-xl p-6">
      <h1 className="mb-4 text-2xl font-bold">Gestor de tareas</h1>
      {error && <p className="mb-2 text-red-600">{error}</p>}
      <div className="mb-4 flex gap-2">
        <input
          className="flex-1 rounded border px-2 py-1"
          placeholder="Tarea"
          value={text}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && add()}
        />
        <button className="rounded bg-blue-600 px-3 py-1 text-white" onClick={add}>
          Agregar
        </button>
      </div>
      <select
        className="mb-4 rounded border px-2 py-1"
        value={filter}
        onChange={(e) => setFilter(e.target.value)}
      >
        <option value="todas">Todas</option>
        <option value="pendientes">Pendientes</option>
        <option value="hechas">Hechas</option>
      </select>
      <ul className="space-y-2">
        {visible.map((t) => (
          <li key={t.id} className="flex items-center gap-2 rounded border p-2">
            {editingId === t.id ? (
              <>
                <input
                  className="flex-1 rounded border px-2 py-1"
                  placeholder="Nuevo título"
                  value={editText}
                  onChange={(e) => setEditText(e.target.value)}
                  onKeyDown={(e) => e.key === "Enter" && save(t.id)}
                />
                <button
                  className="rounded bg-blue-600 px-2 py-1 text-white"
                  onClick={() => save(t.id)}
                >
                  Guardar
                </button>
              </>
            ) : (
              <>
                <span className="flex-1">
                  {t.title}
                  {t.done && " (hecha)"}
                </span>
                {!t.done && (
                  <button
                    className="rounded bg-green-600 px-2 py-1 text-white"
                    onClick={() => update(t.id, { done: true })}
                  >
                    Hecha
                  </button>
                )}
                <button
                  className="rounded bg-gray-600 px-2 py-1 text-white"
                  onClick={() => {
                    setEditingId(t.id);
                    setEditText(t.title);
                  }}
                >
                  Renombrar
                </button>
              </>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
}

