import { createSignal, createMemo, onMount, For, Show } from "solid-js";

interface Task {
  id: number;
  title: string;
  done: boolean;
}

export default function App() {
  const [tasks, setTasks] = createSignal<Task[]>([]);
  const [text, setText] = createSignal("");
  const [filter, setFilter] = createSignal("todas");
  const [editingId, setEditingId] = createSignal<number | null>(null);
  const [editText, setEditText] = createSignal("");

  const load = async () => {
    const r = await fetch("/api/tasks");
    if (r.ok) setTasks(await r.json());
  };

  onMount(load);

  const visible = createMemo(() => {
    const f = filter();
    return tasks().filter((t) =>
      f === "pendientes" ? !t.done : f === "hechas" ? t.done : true
    );
  });

  const add = async () => {
    const title = text().trim();
    if (!title) return;
    const r = await fetch("/api/tasks", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title }),
    });
    if (r.ok) {
      const t: Task = await r.json();
      setTasks((p) => [...p, t]);
      setText("");
    }
  };

  const patch = async (id: number, data: Partial<Task>) => {
    const r = await fetch(`/api/tasks/${id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(data),
    });
    if (r.ok) {
      const t: Task = await r.json();
      setTasks((p) => p.map((x) => (x.id === id ? t : x)));
      return true;
    }
    return false;
  };

  const startEdit = (t: Task) => {
    setEditingId(t.id);
    setEditText(t.title);
  };

  const save = async (id: number) => {
    const title = editText().trim();
    if (!title) return;
    if (await patch(id, { title })) setEditingId(null);
  };

  return (
    <div class="max-w-xl mx-auto p-4 space-y-4">
      <div class="flex gap-2">
        <input
          class="border rounded px-2 py-1 flex-1"
          placeholder="Tarea"
          value={text()}
          onInput={(e) => setText(e.currentTarget.value)}
          onKeyDown={(e) => e.key === "Enter" && add()}
        />
        <button class="bg-blue-500 text-white rounded px-3 py-1" onClick={add}>
          Agregar
        </button>
      </div>

      <select
        class="border rounded px-2 py-1"
        value={filter()}
        onChange={(e) => setFilter(e.currentTarget.value)}
      >
        <option value="todas">Todas</option>
        <option value="pendientes">Pendientes</option>
        <option value="hechas">Hechas</option>
      </select>

      <ul class="space-y-2">
        <For each={visible()}>
          {(t) => (
            <li class="flex items-center gap-2 border rounded p-2">
              <Show
                when={editingId() === t.id}
                fallback={
                  <>
                    <span class="flex-1">
                      {t.title}
                      <Show when={t.done}> (hecha)</Show>
                    </span>
                    <Show when={!t.done}>
                      <button
                        class="bg-green-500 text-white rounded px-2 py-1"
                        onClick={() => patch(t.id, { done: true })}
                      >
                        Hecha
                      </button>
                    </Show>
                    <button
