import { createServer } from "node:http";
import type { IncomingMessage, ServerResponse } from "node:http";

interface Task {
  id: number;
  title: string;
  done: boolean;
}

const tasks: Task[] = [];
let nextId = 1;

function send(res: ServerResponse, status: number, body?: unknown) {
  const data = body === undefined ? "" : JSON.stringify(body);
  res.writeHead(status, {
    "Content-Type": "application/json; charset=utf-8",
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET,POST,PATCH,DELETE,OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type",
  });
  res.end(data);
}

function readBody(req: IncomingMessage): Promise<any> {
  return new Promise((resolve) => {
    let raw = "";
    req.on("data", (c) => (raw += c));
    req.on("end", () => {
      try {
        resolve(raw ? JSON.parse(raw) : {});
      } catch {
        resolve({});
      }
    });
    req.on("error", () => resolve({}));
  });
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url || "/", "http://localhost");
  const path = url.pathname.replace(/\/+$/, "") || "/";
  const method = req.method || "GET";

  if (method === "OPTIONS") return send(res, 204);

  if (path === "/api/tasks" && method === "GET") {
    return send(res, 200, tasks);
  }

  if (path === "/api/tasks" && method === "POST") {
    const body = await readBody(req);
    const title = typeof body.title === "string" ? body.title.trim() : "";
    if (!title) return send(res, 400, { error: "Título requerido" });
    const task: Task = { id: nextId++, title, done: false };
    tasks.push(task);
    return send(res, 201, task);
  }

  const m = path.match(/^\/api\/tasks\/(\d+)$/);
  if (m) {
    const id = Number(m[1]);
    const task = tasks.find((t) => t.id === id);
    if (!task) return send(res, 404, { error: "No encontrada" });

    if (method === "PATCH") {
      const body = await readBody(req);
      if (typeof body.title === "string") {
        const title = body.title.trim();
        if (!title) return send(res, 400, { error: "Título requerido" });
        task.title = title;
      }
      if (typeof body.done === "boolean") task.done = body.done;
      return send(res, 200, task);
    }

    if (method === "DELETE") {
      tasks.splice(tasks.indexOf(task), 1);
      return send(res, 200, task);
    }
  }

  send(res, 404, { error: "Not found" });
});

server.listen(Number(process.env.PORT) || 3000);

