const votes: Record<Choice, number> = { perros: 0, gatos: 0 };

function computeResults() {
  const total = votes.perros + votes.gatos;
  const pct = (n: number) => (total === 0 ? 0 : Math.round((n / total) * 100));
  return {
    perros: { votes: votes.perros, percent: pct(votes.perros) },
    gatos: { votes: votes.gatos, percent: pct(votes.gatos) },
    total,
  };
}

function send(res: ServerResponse, status: number, body: unknown) {
  const data = JSON.stringify(body);
  res.writeHead(status, {
    "Content-Type": "application/json; charset=utf-8",
    "Content-Length": Buffer.byteLength(data),
    "Cache-Control": "no-store",
  });
  res.end(data);
}

function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    let body = "";
    req.on("data", (chunk) => {
      body += chunk;
      if (body.length > 1e5) {
        reject(new Error("Body too large"));
        req.destroy();
      }
    });
    req.on("end", () => resolve(body));
    req.on("error", reject);
  });
}

const server = createServer(async (req, res) => {
  try {
    const url = new URL(req.url ?? "/", "http://localhost");
    const path = url.pathname.replace(/\/+$/, "") || "/";
    const method = req.method ?? "GET";

    if (path === "/api/results" && method === "GET") {
      return send(res, 200, computeResults());
    }

    if (path === "/api/vote" && method === "POST") {
      let parsed: any = null;
      try {
        parsed = JSON.parse((await readBody(req)) || "null");
      } catch {
        return send(res, 400, { error: "JSON inválido" });
      }
      const choice = parsed?.choice;
      if (choice !== "perros" && choice !== "gatos") {
        return send(res, 400, { error: "Opción inválida" });
      }
      votes[choice as Choice]++;
      return send(res, 200, computeResults());
    }

    if (path === "/api/reset" && method === "POST") {
      votes.perros = 0;
      votes.gatos = 0;
      return send(res, 200, computeResults());
    }

    if (path.startsWith("/api/")) {
      return send(res, 404, { error: "No encontrado" });
    }

    send(res, 404, { error: "No encontrado" });
  } catch {
    send(res, 500, { error: "Error interno" });
  }
});

const port = Number(process.env.PORT) || 3000;
server.listen(port, () => {
  console.log(`Servidor escuchando en puerto ${port}`);
});

