import { useCallback, useEffect, useState } from "react";

interface Product {
  id: number;
  name: string;
  num: number;
}

interface Result {
  items: Product[];
  total: number;
  page: number;
  totalPages: number;
}

export default function App() {
  const [query, setQuery] = useState("");
  const [page, setPage] = useState(1);
  const [data, setData] = useState<Result | null>(null);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const load = useCallback(async (q: string, p: number, signal?: AbortSignal) => {
    try {
      const res = await fetch(
        `/api/products?q=${encodeURIComponent(q)}&page=${p}`,
        { signal }
      );
      if (!res.ok) throw new Error("Error del servidor");
      const json: Result = await res.json();
      setData(json);
      setError("");
      if (json.page !== p) setPage(json.page);
    } catch (e) {
      if ((e as Error).name !== "AbortError") setError("No se pudo cargar");
    }
  }, []);

  useEffect(() => {
    const controller = new AbortController();
    load(query, page, controller.signal);
    return () => controller.abort();
  }, [query, page, load]);

  const seed = async () => {
    setLoading(true);
    try {
      const res = await fetch("/api/seed", { method: "POST" });
      if (!res.ok) throw new Error();
      await load(query, page);
    } catch {
      setError("No se pudieron cargar los ejemplos");
    } finally {
      setLoading(false);
    }
  };

  const totalPages = data?.totalPages ?? 1;

  return (
    <div className="min-h-screen bg-gray-100 p-6">
      <div className="mx-auto max-w-md rounded-xl bg-white p-6 shadow">
        <h1 className="mb-4 text-2xl font-bold text-gray-800">Catálogo</h1>

        <button
          onClick={seed}
          disabled={loading}
          className="mb-4 rounded bg-blue-600 px-4 py-2 text-white hover:bg-blue-700 disabled:opacity-50"
        >
          Cargar ejemplos
        </button>

        <input
          type="text"
          placeholder="Buscar"
          value={query}
          onChange={(e) => {
            setQuery(e.target.value);
            setPage(1);
          }}
          className="mb-4 w-full rounded border border-gray-300 px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-400"
        />

        {error && <p className="mb-2 text-sm text-red-600">{error}</p>}

        <p className="mb-2 font-semibold text-gray-700">
          Total: {data ? data.total : 0}
        </p>

        <ul className="mb-4 divide-y divide-gray-200 rounded border border-gray-200">
          {data?.items.map((p) => (
            <li key={p.id} className="px-3 py-2 text-gray-800">
              {p.name}
            </li>
          ))}
          {data && data.items.length === 0 && (
            <li className="px-3 py-2 text-gray-400">Sin productos</li>
          )}
        </ul>

        <div className="flex items-center justify-between">
          <button
            onClick={() => setPage((p) => Math.max(1, p - 1))}
            disabled={page <= 1}
            className="rounded bg-gray-200 px-4 py-2 hover:bg-gray-300 disabled:opacity-50"
          >
            Anterior
          </button>
          <span className="text-sm text-gray-600">
            Página {data?.page ?? 1} de {totalPages}
          </span>
          <button
            onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
            disabled={page >= totalPages}
            className="rounded bg-gray-200 px-4 py-2 hover:bg-gray-300 disabled:opacity-50"
          >
            Siguiente
          </button>
        </div>
      </div>
    </div>
  );
}

