import { useCallback, useEffect, useState } from "react";

interface Product {
  id: number;
  name: string;
  num: number;
}

interface ListResponse {
  items: Product[];
  total: number;
  page: number;
  pageSize: number;
  totalPages: number;
}

export default function App() {
  const [query, setQuery] = useState("");
  const [page, setPage] = useState(1);
  const [data, setData] = useState<ListResponse | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [seeding, setSeeding] = useState(false);

  const load = useCallback(async (q: string, p: number, signal?: AbortSignal) => {
    try {
      const res = await fetch(
        `/api/products?q=${encodeURIComponent(q)}&page=${p}`,
        { signal }
      );
      if (!res.ok) throw new Error("Error del servidor");
      const json: ListResponse = await res.json();
      setData(json);
      setError(null);
    } catch (e) {
      if ((e as Error).name === "AbortError") return;
      setError("No se pudo cargar la lista");
    }
  }, []);

  useEffect(() => {
    const controller = new AbortController();
    load(query, page, controller.signal);
    return () => controller.abort();
  }, [query, page, load]);

  const seed = async () => {
    setSeeding(true);
    try {
      const res = await fetch("/api/seed", { method: "POST" });
      if (!res.ok) throw new Error();
      await load(query, page);
    } catch {
      setError("No se pudieron cargar los ejemplos");
    } finally {
      setSeeding(false);
    }
  };

  const totalPages = data?.totalPages ?? 1;
  const current = data?.page ?? page;

  return (
    <div className="min-h-screen bg-gray-100 p-6">
      <div className="mx-auto max-w-xl rounded-lg bg-white p-6 shadow">
        <h1 className="mb-4 text-2xl font-bold text-gray-800">Catálogo</h1>

        <div className="mb-4 flex gap-2">
          <input
            type="text"
            placeholder="Buscar"
            value={query}
            onChange={(e) => {
              setQuery(e.target.value);
              setPage(1);
            }}
            className="flex-1 rounded border border-gray-300 px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-400"
          />
          <button
            onClick={seed}
            disabled={seeding}
            className="rounded bg-blue-600 px-4 py-2 text-white hover:bg-blue-700 disabled:opacity-50"
          >
            Cargar ejemplos
          </button>
        </div>

        {error && <p className="mb-2 text-red-600">{error}</p>}

        <p className="mb-2 font-medium text-gray-700">Total: {data?.total ?? 0}</p>

        <ul className="mb-4 divide-y divide-gray-200 rounded border border-gray-200">
          {data?.items.map((p) => (
            <li key={p.id} className="px-4 py-2 text-gray-800">
              {p.name}
            </li>
          ))}
          {data && data.items.length === 0 && (
            <li className="px-4 py-2 text-gray-500">Sin productos</li>
          )}
        </ul>

        <div className="flex items-center justify-between">
          <button
            onClick={() => setPage((p) => Math.max(1, p - 1))}
            disabled={current <= 1}
            className="rounded bg-gray-200 px-4 py-2 hover:bg-gray-300 disabled:opacity-50"
          >
            Anterior
          </button>
          <span className="text-sm text-gray-600">
            Página {current} de {totalPages}
          </span>
          <button
            onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
            disabled={current >= totalPages}
            className="rounded bg-gray-200 px-4 py-2 hover:bg-gray-300 disabled:opacity-50"
          >
            Siguiente
          </button>
        </div>
      </div>
    </div>
  );
}

