import { createServer, IncomingMessage, ServerResponse } from "node:http";

interface Product {
  id: number;
  name: string;
  num: number;
}

const products: Product[] = [];
const PAGE_SIZE = 5;

function send(res: ServerResponse, status: number, body: unknown) {
  const data = JSON.stringify(body);
  res.writeHead(status, {
    "Content-Type": "application/json; charset=utf-8",
    "Content-Length": Buffer.byteLength(data),
  });
  res.end(data);
}

function naturalNum(name: string): number {
  const m = name.match(/(\d+)\s*$/);
  return m ? parseInt(m[1], 10) : Number.MAX_SAFE_INTEGER;
}

function handle(req: IncomingMessage, res: ServerResponse) {
  const url = new URL(req.url || "/", "http://localhost");
  const path = url.pathname;

  if (req.method === "GET" && path === "/api/products") {
    const q = (url.searchParams.get("q") || "").trim().toLowerCase();
    let page = parseInt(url.searchParams.get("page") || "1", 10);
    if (!Number.isFinite(page) || page < 1) page = 1;

    const filtered = products
      .filter((p) => p.name.toLowerCase().includes(q))
      .sort((a, b) => a.num - b.num || a.name.localeCompare(b.name));
    const total = filtered.length;
    const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));
    if (page > totalPages) page = totalPages;
    const items = filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);
    return send(res, 200, { items, total, page, pageSize: PAGE_SIZE, totalPages });
  }

  if (req.method === "POST" && path === "/api/seed") {
    let created = false;
    if (products.length === 0) {
      for (let i = 1; i <= 12; i++) {
        const name = `Producto ${i}`;
        products.push({ id: i, name, num: naturalNum(name) });
      }
      created = true;
    }
    return send(res, 200, { created, total: products.length });
  }

  send(res, 404, { error: "Not found" });
}

const port = Number(process.env.PORT) || 3000;
createServer((req, res) => {
  try {
    handle(req, res);
  } catch (e) {
    send(res, 500, { error: "Internal error" });
  }
}).listen(port, () => {
  console.log(`Server listening on ${port}`);
});

