import { createSignal, createResource, For, Show } from "solid-js";

interface Product {
  id: number;
  name: string;
  num: number;
}

interface PageData {
  items: Product[];
  total: number;
  page: number;
  pageSize: number;
  totalPages: number;
}

export default function App() {
  const [query, setQuery] = createSignal("");
  const [page, setPage] = createSignal(1);

  const [data, { refetch }] = createResource(
    () => ({ q: query(), page: page() }),
    async ({ q, page }): Promise<PageData> => {
      const res = await fetch(
        `/api/products?q=${encodeURIComponent(q)}&page=${page}`
      );
      return res.json();
    }
  );

  const seed = async () => {
    await fetch("/api/seed", { method: "POST" });
    setPage(1);
    refetch();
  };

  const onSearch = (v: string) => {
    setQuery(v);
    setPage(1);
  };

  const current = () => data.latest;
  const totalPages = () => current()?.totalPages ?? 1;

  return (
    <div class="max-w-md mx-auto p-6 space-y-4">
      <h1 class="text-2xl font-bold">Catálogo</h1>

      <button
        class="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700"
        onClick={seed}
      >
        Cargar ejemplos
      </button>

      <input
        type="text"
        placeholder="Buscar"
        class="w-full border rounded px-3 py-2"
        value={query()}
        onInput={(e) => onSearch(e.currentTarget.value)}
      />

      <p class="text-gray-700">Total: {current()?.total ?? 0}</p>

      <ul class="divide-y border rounded">
        <For each={current()?.items ?? []}>
          {(p) => <li class="px-3 py-2">{p.name}</li>}
        </For>
      </ul>

      <Show when={(current()?.items.length ?? 0) === 0 && !data.loading}>
        <p class="text-gray-500 text-sm">Sin productos</p>
      </Show>

      <div class="flex items-center gap-3">
        <button
          class="px-3 py-1 border rounded disabled:opacity-50"
          disabled={page() <= 1}
          onClick={() => setPage((p) => Math.max(1, p - 1))}
        >
          Anterior
        </button>
        <span class="text-sm text-gray-600">
          {page()} / {totalPages()}
        </span>
        <button
          class="px-3 py-1 border rounded disabled:opacity-50"
          disabled={page() >= totalPages()}
          onClick={() => setPage((p) => p + 1)}
        >
          Siguiente
        </button>
      </div>
    </div>
  );
}

