model User {
  id: ID
  email: Email unique
  password: String
}

model Note {
  id: ID
  text: String min=1 max=500
  owner: ID
}

auth users: User
api notes: Note private

page Home "/" {
  state email = ""
  state password = ""
  state error = ""
  state draft = ""

  data me = auth.me()
  data list = api.notes.list()

  fn signup() {
    error = ""
    try {
      auth.signup({ email: email, password: password })
      password = ""
    } catch (e) {
      error = e.message
    }
  }

  fn login() {
    error = ""
    try {
      auth.login(email, password)
      password = ""
    } catch (e) {
      error = "Datos incorrectos"
    }
  }

  fn logout() {
    auth.logout()
  }

  fn add() {
    if draft == "" { return }
    try {
      api.notes.create({ text: draft })
      draft = ""
    } catch (e) {
      notify(e.message, "danger")
    }
  }

  column gap=4 pad=4 {
    title "Notas privadas"
    if me {
      row gap=2 align=center {
        text `Hola, ${me.email}`
        button "Salir" -> logout()
