import { useEffect, useState } from "react";

type Note = { id: number; text: string };

export default function App() {
  const [token, setToken] = useState<string | null>(() => localStorage.getItem("token"));
  const [user, setUser] = useState<string | null>(null);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [notes, setNotes] = useState<Note[]>([]);
  const [text, setText] = useState("");
  const [loading, setLoading] = useState(!!localStorage.getItem("token"));

  const headers = (t: string) => ({
    "Content-Type": "application/json",
    Authorization: `Bearer ${t}`,
  });

  const logout = () => {
    if (token) {
      fetch("/api/logout", { method: "POST", headers: headers(token) }).catch(() => {});
    }
    localStorage.removeItem("token");
    setToken(null);
    setUser(null);
    setNotes([]);
    setText("");
  };

  useEffect(() => {
    if (!token) {
      setLoading(false);
      return;
    }
    let cancelled = false;
    (async () => {
      try {
        const r = await fetch("/api/me", { headers: headers(token) });
        if (!r.ok) throw new Error();
        const me = await r.json();
        const n = await fetch("/api/notes", { headers: headers(token) });
        const list = await n.json();
        if (!cancelled) {
          setUser(me.email);
          setNotes(list);
        }
      } catch {
        if (!cancelled) {
          localStorage.removeItem("token");
          setToken(null);
          setUser(null);
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [token]);

  const auth = async (mode: "register" | "login") => {
    setError("");
    try {
      const r = await fetch(`/api/${mode}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
      });
      const data = await r.json().catch(() => ({}));
      if (!r.ok) {
        setError(mode === "login" ? "Datos incorrectos" : data.error || "Error");
        return;
      }
      localStorage.setItem("token", data.token);
      setPassword("");
      setLoading(true);
      setToken(data.token);
    } catch {
      setError("Error de conexión");
    }
  };

  const addNote = async () => {
    if (!token || !text.trim()) return;
    const r = await fetch("/api/notes", {
      method: "POST",
      headers: headers(token),
      body: JSON.stringify({ text }),
    });
    if (r.ok) {
      const note = await r.json();
      setNotes((n) => [...n, note]);
      setText("");
    } else if (r.status === 401) logout();
  };

  const input = "border rounded px-3 py-2 w-full";
  const btn = "bg-blue-600 text-white rounded px-4 py-2 hover:bg-blue-700";

  if (loading) {
    return <div className="min-h-screen flex items-center justify-center text-gray-500">Cargando...</div>;
  }

  return (
    <div className="min-h-screen bg-gray-100 flex items-start justify-center p-6">
      <div className="bg-white rounded-lg shadow p-6 w-full max-w-md space-y-4">
        {!token || !user ? (
          <>
            <h1 className="text-xl font-bold">Notas privadas</h1>
            <input
              className={input}
              placeholder="Email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />
            <input
              className={input}
              type="password"
              placeholder="Contraseña"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
            <div className="flex gap-2">
              <button className={btn} onClick={() => auth("register")}>
                Crear cuenta
              </button>
              <button className={btn} onClick={() => auth("login")}>
                Entrar
              </button>
            </div>
            {error && <p className="text-red-600">{error}</p>}
          </>
        ) : (
          <>
            <div className="flex items-center justify-between">
              <p className="font-semibold">Hola, {user}</p>
              <button className={btn} onClick={logout}>
                Salir
              </button>
            </div>
            <div className="flex gap-2">
              <input
                className={input}
                placeholder="Nota"
                value={text}
                onChange={(e) => setText(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && addNote()}
              />
              <button className={btn} onClick={addNote}>
                Agregar
              </button>
            </div>
            <ul className="space-y-2">
              {notes.map((n) => (
                <li key={n.id} className="border rounded px-3 py-2">
                  {n.text}
                </li>
              ))}
            </ul>
          </>
        )}
      </div>
    </div>
  );
}

