import http from "node:http";
import crypto from "node:crypto";

type User = { id: number; email: string; salt: string; hash: string };
type Note = { id: number; text: string };

const users = new Map<string, User>();
const sessions = new Map<string, number>();
const notesByUser = new Map<number, Note[]>();
let userSeq = 1;
let noteSeq = 1;

const hashPassword = (password: string, salt: string) =>
  crypto.scryptSync(password, salt, 64).toString("hex");

const send = (res: http.ServerResponse, status: number, body: unknown) => {
  res.writeHead(status, { "Content-Type": "application/json" });
  res.end(JSON.stringify(body));
};

const readBody = (req: http.IncomingMessage): Promise<any> =>
  new Promise((resolve) => {
    let data = "";
    req.on("data", (c) => {
      data += c;
      if (data.length > 1e6) req.destroy();
    });
    req.on("end", () => {
      try {
        resolve(JSON.parse(data || "{}"));
      } catch {
        resolve({});
      }
    });
    req.on("error", () => resolve({}));
  });

const getToken = (req: http.IncomingMessage) => {
  const h = req.headers.authorization || "";
  return h.startsWith("Bearer ") ? h.slice(7) : null;
};

const getUserId = (req: http.IncomingMessage) => {
  const t = getToken(req);
  return t ? sessions.get(t) : undefined;
};

const findById = (id: number) => {
  for (const u of users.values()) if (u.id === id) return u;
  return undefined;
};

const newSession = (userId: number) => {
  const token = crypto.randomBytes(32).toString("hex");
  sessions.set(token, userId);
  return token;
};

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url || "/", "http://localhost");
  const path = url.pathname;
  const method = req.method;

  if (!path.startsWith("/api/")) return send(res, 404, { error: "No encontrado" });

  if (method === "POST" && (path === "/api/register" || path === "/api/login")) {
    const body = await readBody(req);
    const email = typeof body.email === "string" ? body.email.trim().toLowerCase() : "";
    const password = typeof body.password === "string" ? body.password : "";

    if (path === "/api/register") {
      if (!email || !password) return send(res, 400, { error: "Email y contraseña requeridos" });
      if (users.has(email)) return send(res, 409, { error: "El email ya está registrado" });
      const salt = crypto.randomBytes(16).toString("hex");
      const user: User = { id: userSeq++, email, salt, hash: hashPassword(password, salt) };
      users.set(email, user);
      notesByUser.set(user.id, []);
      return send(res, 200, { token: newSession(user.id), email });
    }

    const user = users.get(email);
    if (!user || !password) return send(res, 401, { error: "Datos incorrectos" });
    const a = Buffer.from(hashPassword(password, user.salt), "hex");
    const b = Buffer.from(user.hash, "hex");
    if (a.length !== b.length || !crypto.timingSafeEqual(a, b))
      return send(res, 401, { error: "Datos incorrectos" });
    return send(res, 200, { token: newSession(user.id), email });
  }

  if (method === "POST" && path === "/api/logout") {
    const t = getToken(req);
    if (t) sessions.delete(t);
    return send(res, 200, { ok: true });
  }

  const uid = getUserId(req);
  if (uid === undefined) return send(res, 401, { error: "No autorizado" });

  if (method === "GET" && path === "/api/me") {
    const u = findById(uid);
    if (!u) return send(res, 401, { error: "No autorizado" });
    return send(res, 200, { email: u.email });
  }

  if (path === "/api/notes") {
    if (method === "GET") return send(res, 200, notesByUser.get(uid) || []);
    if (method === "POST") {
      const body = await readBody(req);
      const text = typeof body.text === "string" ? body.text.trim() : "";
      if (!text) return send(res, 400, { error: "Nota vacía" });
      const note: Note = { id: noteSeq++, text };
      const list = notesByUser.get(uid) || [];
      list.push(note);
      notesByUser.set(uid, list);
      return send(res, 200, note);
    }
  }

  send(res, 404, { error: "No encontrado" });
});

server.listen(Number(process.env.PORT) || 3000);

