            </div>
            {error && <p className="text-red-600">{error}</p>}
          </form>
        ) : (
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <span>Hola, {email}</span>
              <button className={btnCls} onClick={logout}>
