import http from "node:http";
import crypto from "node:crypto";

type User = { email: string; salt: string; hash: string };
type Note = { id: number; text: string };

const users = new Map<string, User>();
const sessions = new Map<string, string>();
const notes = new Map<string, Note[]>();
let nextId = 1;

const hashPw = (pw: string, salt: string) =>
  crypto.scryptSync(pw, salt, 64).toString("hex");

function send(res: http.ServerResponse, status: number, body: unknown) {
  res.writeHead(status, { "Content-Type": "application/json" });
  res.end(JSON.stringify(body));
}

function readBody(req: http.IncomingMessage): Promise<any> {
  return new Promise((resolve) => {
    let data = "";
    req.on("data", (c) => {
      data += c;
      if (data.length > 1e6) req.destroy();
    });
    req.on("end", () => {
      try {
        resolve(JSON.parse(data || "{}"));
      } catch {
        resolve({});
      }
    });
    req.on("error", () => resolve({}));
  });
}

function authEmail(req: http.IncomingMessage): string | null {
  const h = req.headers.authorization || "";
  const t = h.startsWith("Bearer ") ? h.slice(7) : "";
  return sessions.get(t) || null;
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url || "/", "http://localhost");
  const path = url.pathname;
  if (!path.startsWith("/api/")) return send(res, 404, { error: "No encontrado" });

  if (req.method === "POST" && (path === "/api/register" || path === "/api/login")) {
    const body = await readBody(req);
    const email = typeof body.email === "string" ? body.email.trim().toLowerCase() : "";
    const password = typeof body.password === "string" ? body.password : "";
    if (path === "/api/register") {
      if (!email || !password) return send(res, 400, { error: "Email y contraseña requeridos" });
      if (users.has(email)) return send(res, 409, { error: "La cuenta ya existe" });
      const salt = crypto.randomBytes(16).toString("hex");
      users.set(email, { email, salt, hash: hashPw(password, salt) });
      notes.set(email, []);
    } else {
      const u = users.get(email);
      let ok = false;
      if (u) {
        const a = Buffer.from(hashPw(password, u.salt), "hex");
        const b = Buffer.from(u.hash, "hex");
        ok = a.length === b.length && crypto.timingSafeEqual(a, b);
      }
      if (!ok) return send(res, 401, { error: "Datos incorrectos" });
    }
    const token = crypto.randomBytes(32).toString("hex");
    sessions.set(token, email);
    return send(res, 200, { token, email });
  }

  if (req.method === "POST" && path === "/api/logout") {
    const h = req.headers.authorization || "";
    sessions.delete(h.startsWith("Bearer ") ? h.slice(7) : "");
    return send(res, 200, { ok: true });
  }

  if (path === "/api/notes") {
    const email = authEmail(req);
    if (!email) return send(res, 401, { error: "No autorizado" });
    if (req.method === "GET") return send(res, 200, notes.get(email) || []);
    if (req.method === "POST") {
      const body = await readBody(req);
      const text = typeof body.text === "string" ? body.text.trim() : "";
      if (!text) return send(res, 400, { error: "Nota vacía" });
      const n: Note = { id: nextId++, text };
      const list = notes.get(email) || [];
      list.push(n);
      notes.set(email, list);
      return send(res, 201, n);
    }
  }

  send(res, 404, { error: "No encontrado" });
});

server.listen(Number(process.env.PORT) || 3000);

import http from 'node:http';
import crypto from 'node:crypto';

type User = { email: string; salt: string; hash: string };
type Note = { id: number; text: string };

const users = new Map<string, User>();
const notesByUser = new Map<string, Note[]>();
const sessions = new Map<string, string>();
let nextId = 1;

function hashPassword(password: string, salt: string): string {
  return crypto.scryptSync(password, salt, 64).toString('hex');
}

function send(res: http.ServerResponse, status: number, data: unknown, headers: Record<string, string> = {}) {
  res.writeHead(status, { 'Content-Type': 'application/json', ...headers });
  res.end(JSON.stringify(data));
}

function readBody(req: http.IncomingMessage): Promise<any> {
  return new Promise((resolve) => {
    let raw = '';
    req.on('data', (c) => {
      raw += c;
      if (raw.length > 1e6) req.destroy();
    });
    req.on('end', () => {
      try {
        resolve(raw ? JSON.parse(raw) : {});
      } catch {
        resolve({});
      }
    });
    req.on('error', () => resolve({}));
  });
}

function getToken(req: http.IncomingMessage): string | null {
  const cookie = req.headers.cookie ?? '';
  for (const part of cookie.split(';')) {
    const [k, ...v] = part.trim().split('=');
    if (k === 'sid') return v.join('=');
  }
  return null;
}

function getUser(req: http.IncomingMessage): string | null {
  const t = getToken(req);
  return t ? (sessions.get(t) ?? null) : null;
}

function startSession(res: http.ServerResponse, email: string) {
  const token = crypto.randomBytes(32).toString('hex');
  sessions.set(token, email);
  send(res, 200, { email }, { 'Set-Cookie': `sid=${token}; HttpOnly; Path=/; SameSite=Lax` });
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url ?? '/', 'http://localhost');
  const path = url.pathname;
  const method = req.method ?? 'GET';

  if (!path.startsWith('/api/')) return send(res, 404, { error: 'No encontrado' });

  if (path === '/api/register' && method === 'POST') {
    const { email, password } = await readBody(req);
    if (typeof email !== 'string' || typeof password !== 'string' || !email.trim() || !password) {
