const notesByUser = new Map<string, Note[]>();
const sessions = new Map<string, string>();
let nextId = 1;

function hashPassword(password: string, salt: string): string {
  return crypto.scryptSync(password, salt, 64).toString("hex");
}

function send(
  res: http.ServerResponse,
  status: number,
  data: unknown,
  headers: Record<string, string> = {},
) {
  res.writeHead(status, { "Content-Type": "application/json", ...headers });
  res.end(JSON.stringify(data));
}

function readBody(req: http.IncomingMessage): Promise<any> {
  return new Promise((resolve) => {
    let raw = "";
    req.on("data", (c) => {
      raw += c;
      if (raw.length > 1e6) req.destroy();
    });
    req.on("end", () => {
      try {
        resolve(raw ? JSON.parse(raw) : {});
      } catch {
        resolve({});
      }
    });
    req.on("error", () => resolve({}));
  });
}

function getSession(req: http.IncomingMessage): { token: string; email: string } | null {
  const cookie = req.headers.cookie || "";
  for (const part of cookie.split(";")) {
    const [k, ...v] = part.trim().split("=");
    if (k === "sid") {
      const token = v.join("=");
      const email = sessions.get(token);
      if (email) return { token, email };
    }
  }
  return null;
}

function startSession(res: http.ServerResponse, email: string) {
  const token = crypto.randomBytes(32).toString("hex");
  sessions.set(token, email);
  return { "Set-Cookie": `sid=${token}; HttpOnly; Path=/; SameSite=Lax` };
}

