import { createServer, IncomingMessage, ServerResponse } from "node:http";
import { randomBytes, scryptSync, timingSafeEqual } from "node:crypto";

interface User {
  id: string;
  email: string;
  salt: string;
  hash: string;
}
interface Note {
  id: string;
  text: string;
}

const users = new Map<string, User>(); // por email normalizado
const sessions = new Map<string, string>(); // token -> user id
const notes = new Map<string, Note[]>(); // user id -> notas

function hashPassword(password: string, salt: string): string {
  return scryptSync(password, salt, 64).toString("hex");
}

function send(res: ServerResponse, status: number, data: unknown) {
  res.writeHead(status, { "Content-Type": "application/json; charset=utf-8" });
  res.end(JSON.stringify(data));
}

function readBody(req: IncomingMessage): Promise<any> {
  return new Promise((resolve) => {
    let raw = "";
    req.on("data", (c) => {
      raw += c;
      if (raw.length > 1e6) req.destroy();
    });
    req.on("end", () => {
      try {
        resolve(raw ? JSON.parse(raw) : {});
      } catch {
        resolve({});
      }
    });
    req.on("error", () => resolve({}));
  });
}

function authUser(req: IncomingMessage): User | null {
  const h = req.headers["authorization"] || "";
  const m = /^Bearer (.+)$/.exec(Array.isArray(h) ? h[0] : h);
  if (!m) return null;
  const uid = sessions.get(m[1]);
  if (!uid) return null;
  for (const u of users.values()) if (u.id === uid) return u;
  return null;
}

function newSession(userId: string): string {
  const token = randomBytes(32).toString("hex");
  sessions.set(token, userId);
  return token;
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url || "/", "http://localhost");
  const path = url.pathname;
  const method = req.method || "GET";

  if (!path.startsWith("/api/")) return send(res, 404, { error: "No encontrado" });

  try {
    if (method === "POST" && path === "/api/register") {
      const body = await readBody(req);
      const email = String(body.email ?? "").trim().toLowerCase();
      const password = String(body.password ?? "");
      if (!email || !password) return send(res, 400, { error: "Faltan datos" });
      if (users.has(email)) return send(res, 409, { error: "El email ya existe" });
      const salt = randomBytes(16).toString("hex");
      const user: User = {
        id: randomBytes(8).toString("hex"),
        email,
        salt,
        hash: hashPassword(password, salt),
      };
      users.set(email, user);
      notes.set(user.id, []);
      const token = newSession(user.id);
      return send(res, 201, { token, email: user.email });
    }

    if (method === "POST" && path === "/api/login") {
      const body = await readBody(req);
      const email = String(body.email ?? "").trim().toLowerCase();
      const password = String(body.password ?? "");
      const user = users.get(email);
      if (!user) {
        hashPassword(password, "0000000000000000"); // mitiga timing
        return send(res, 401, { error: "Datos incorrectos" });
      }
      const a = Buffer.from(hashPassword(password, user.salt), "hex");
      const b = Buffer.from(user.hash, "hex");
      if (a.length !== b.length || !timingSafeEqual(a, b))
        return send(res, 401, { error: "Datos incorrectos" });
      const token = newSession(user.id);
      return send(res, 200, { token, email: user.email });
    }

    if (method === "POST" && path === "/api/logout") {
      const h = String(req.headers["authorization"] || "");
      const m = /^Bearer (.+)$/.exec(h);
      if (m) sessions.delete(m[1]);
      return send(res, 200, { ok: true });
    }

    if (path === "/api/me" && method === "GET") {
      const user = authUser(req);
      if (!user) return send(res, 401, { error: "No autorizado" });
      return send(res, 200, { email: user.email });
    }

    if (path === "/api/notes") {
      const user = authUser(req);
      if (!user) return send(res, 401, { error: "No autorizado" });
      if (method === "GET") return send(res, 200, notes.get(user.id) ?? []);
      if (method === "POST") {
        const body = await readBody(req);
        const text = String(body.text ?? "").trim();
        if (!text) return send(res, 400, { error: "Nota vacía" });
        const note: Note = { id: randomBytes(8).toString("hex"), text };
        const list = notes.get(user.id) ?? [];
        list.push(note);
        notes.set(user.id, list);
        return send(res, 201, note);
      }
    }

    return send(res, 404, { error: "No encontrado" });
  } catch {
    return send(res, 500, { error: "Error interno" });
  }
});

server.listen(Number(process.env.PORT) || 3000);

