import { createSignal, For, Show, onMount } from "solid-js";

interface Note {
  id: string;
  text: string;
}

export default function App() {
  const [email, setEmail] = createSignal("");
  const [password, setPassword] = createSignal("");
  const [token, setToken] = createSignal<string | null>(null);
  const [user, setUser] = createSignal<string | null>(null);
  const [error, setError] = createSignal("");
  const [notes, setNotes] = createSignal<Note[]>([]);
  const [text, setText] = createSignal("");

  const headers = (t: string) => ({
    "Content-Type": "application/json",
    Authorization: `Bearer ${t}`,
  });

  async function loadNotes(t: string) {
    const r = await fetch("/api/notes", { headers: headers(t) });
    if (r.ok) setNotes(await r.json());
  }

  async function auth(kind: "register" | "login") {
    setError("");
    try {
      const r = await fetch(`/api/${kind}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: email(), password: password() }),
      });
      const data = await r.json().catch(() => ({}));
      if (!r.ok) {
        setError(
          kind === "login" ? "Datos incorrectos" : data.error || "Error"
        );
        return;
      }
      setToken(data.token);
      setUser(data.email);
      setPassword("");
      await loadNotes(data.token);
    } catch {
      setError("Error de conexión");
    }
  }

  async function logout() {
    const t = token();
    if (t) await fetch("/api/logout", { method: "POST", headers: headers(t) }).catch(() => {});
    setToken(null);
    setUser(null);
    setNotes([]);
    setEmail("");
    setPassword("");
    setText("");
    setError("");
  }

  async function addNote() {
    const t = token();
    const v = text().trim();
    if (!t || !v) return;
    const r = await fetch("/api/notes", {
      method: "POST",
      headers: headers(t),
      body: JSON.stringify({ text: v }),
    });
    if (r.ok) {
      const n: Note = await r.json();
      setNotes((l) => [...l, n]);
      setText("");
    }
  }

  return (
    <div class="min-h-screen bg-gray-100 flex items-start justify-center p-6">
      <div class="w-full max-w-md bg-white rounded-lg shadow p-6 space-y-4">
        <h1 class="text-xl font-bold">Notas privadas</h1>
        <Show
          when={user()}
          fallback={
            <div class="space-y-3">
              <input
                class="w-full border rounded px-3 py-2"
                placeholder="Email"
                value={email()}
                onInput={(e) => setEmail(e.currentTarget.value)}
              />
              <input
                class="w-full border rounded px-3 py-2"
                type="password"
                placeholder="Contraseña"
                value={password()}
                onInput={(e) => setPassword(e.currentTarget.value)}
              />
              <div class="flex gap-2">
                <button
                  class="px-4 py-2 rounded bg-blue-600 text-white"
                  onClick={() => auth("register")}
                >
                  Crear cuenta
                </button>
                <button
                  class="px-4 py-2 rounded bg-gray-800 text-white"
                  onClick={() => auth("login")}
                >
                  Entrar
                </button>
              </div>
              <Show when={error()}>
                <p class="text-red-600">{error()}</p>
              </Show>
            </div>
          }
        >
          <div class="space-y-3">
            <div class="flex items-center justify-between">
              <span>Hola, {user()}</span>
              <button
                class="px-3 py-1 rounded bg-gray-200"
                onClick={logout}
              >
                Salir
              </button>
            </div>
            <div class="flex gap-2">
              <input
                class="flex-1 border rounded px-3 py-2"
                placeholder="Nota"
                value={text()}
                onInput={(e) => setText(e.currentTarget.value)}
                onKeyDown={(e) => e.key === "Enter" && addNote()}
              />
              <button
                class="px-4 py-2 rounded bg-blue-600 text-white"
                onClick={addNote}
              >
                Agregar
              </button>
            </div>
            <ul class="space-y-2">
              <For each={notes()}>
                {(n) => <li class="border rounded px-3 py-2">{n.text}</li>}
              </For>
            </ul>
          </div>
        </Show>
      </div>
    </div>
  );
}

files.components.art:
component Header(count: Number) {
  row justify=between {
    title "Tienda"
    text `Carrito (${count})` muted
  }
}

component Nav(tab: String, onChange: Fn) {
  row gap=2 {
    button "Catálogo" primary=(tab == "catalog") -> onChange("catalog")
    button "Carrito" primary=(tab == "cart") -> onChange("cart")
  }
}

component Catalog(products: Product[], onAdd: Fn) {
  state query = ""
  computed shown = products.filter(p => p.name.toLowerCase().includes(query.toLowerCase()))

  column gap=2 {
    input query placeholder="Buscar"
    grid cols=3 gap=2 {
      for p in shown {
        ProductCard product=p onAdd=onAdd
      }
    }
    if shown.length == 0 {
      text "Sin resultados" muted
    }
  }
}

component ProductCard(product: Product, onAdd: Fn) {
  card gap=1 {
    text product.name bold
    text `$${product.price.toFixed(2)}`
    button "Agregar" primary -> onAdd(product)
  }
}

component CartView(cart: CartItem[], onChangeQty: Fn, onClear: Fn, onRemove: Fn) {
  if cart.length == 0 {
    text "El carrito está vacío" muted
  } else {
    column gap=2 {
      for item in cart {
        CartItemRow item=item onChangeQty=onChangeQty onRemove=onRemove
      }
      Summary cart=cart onClear=onClear
    }
  }
}

component CartItemRow(item: CartItem, onChangeQty: Fn, onRemove: Fn) {
  row gap=2 {
    text item.product.name
    button "-" -> onChangeQty(item.product.id, -1)
    text item.qty
    button "+" -> onChangeQty(item.product.id, 1)
    text `$${(item.product.price * item.qty).toFixed(2)}`
    button "Quitar" danger small -> onRemove(item.product.id)
  }
}

component Summary(cart: CartItem[], onClear: Fn) {
  computed total = cart.reduce((sum, i) => sum + i.product.price * i.qty, 0)

  row justify=between {
    text `Total: $${total.toFixed(2)}` bold
    button "Vaciar carrito" danger -> onClear()
  }
}

component Footer {
  text "Gracias por visitar la tienda" small muted
}

