      <span className="font-semibold">
        {item.name}
        {!item.active && <span className="font-normal text-gray-500"> (inactivo)</span>}
      </span>
      <span>Sueldo: {item.amount}</span>
      <button onClick={() => onToggle(item.id)}>Alternar</button>
    </div>
  );
}

