export default function CouponsForm({ onAdd }: { onAdd: (name: string, amount: number) => void }) {
  const [name, setName] = useState("");
  const [amount, setAmount] = useState("");

  function submit() {
    onAdd(name, Number(amount) || 0);
    setName("");
    setAmount("");
  }

  return (
    <div className="flex gap-2">
      <input placeholder="Nombre" value={name} onChange={(e) => setName(e.target.value)} />
      <input placeholder="Descuento" type="number" value={amount} onChange={(e) => setAmount(e.target.value)} />
      <button className="primary" onClick={submit}>Agregar</button>
    </div>
  );
}

files.CouponsList.tsx:
import type { Item } from "./data";
import CouponsRow from "./CouponsRow";

export default function CouponsList({
  items,
  onDelete,
}: {
  items: Item[];
  onDelete: (id: number) => void;
}) {
  if (items.length === 0) return <span className="text-gray-500">Sin registros</span>;
  return (
    <div className="flex flex-col gap-1">
      {items.map((item) => (
        <CouponsRow key={item.id} item={item} onDelete={onDelete} />
      ))}
    </div>
  );
}

files.CouponsPage.tsx:
import { useState } from "react";
import { SEED, type Item } from "./data";
import CouponsForm from "./CouponsForm";
import CouponsList from "./CouponsList";

export default function CouponsPage() {
  const [items, setItems] = useState<Item[]>(SEED.map((i) => ({ ...i })));

  function add(name: string, amount: number) {
    setItems([...items, { id: Date.now(), name, amount, active: true }]);
  }

  function remove(id: number) {
    setItems((prev) => prev.filter((i) => i.id !== id));
  }

  return (
    <div className="flex flex-col gap-2">
      <h2 className="text-xl font-bold">Cupones</h2>
      <CouponsForm onAdd={add} />
      <CouponsList items={items} onDelete={remove} />
    </div>
  );
}

files.CouponsRow.tsx:
import type { Item } from "./data";

export default function CouponsRow({
  item,
  onDelete,
}: {
  item: Item;
  onDelete: (id: number) => void;
}) {
  return (
    <div className="flex gap-2">
      <span className="font-semibold">{item.name}</span>
      <span>Descuento: {item.amount}</span>
      <button
        type="button"
        className="rounded bg-red-600 px-2 text-white hover:bg-red-700"
        onClick={() => onDelete(item.id)}
      >
        Eliminar
      </button>
    </div>
  );
}

