import type { Item } from "./data";

import { Show } from "solid-js";

export default function EmployeesRow(props: { item: Item; onToggle: (id: number) => void }) {
  return (
    <div class="flex gap-2 items-center">
      <span class="font-semibold">{props.item.name}</span>
      <Show when={!props.item.active}>
        <span class="text-gray-500">(inactivo)</span>
      </Show>
      <span>Sueldo: {props.item.amount}</span>
      <button
        type="button"
        class="px-2 py-0.5 border rounded"
        onClick={() => props.onToggle(props.item.id)}
      >
        Alternar
      </button>
    </div>
  );
}

