files.CustomersForm.tsx:
import { useState } from "react";

export default function CustomersForm({ onAdd }: { onAdd: (name: string, amount: number) => void }) {
  const [name, setName] = useState("");
  const [amount, setAmount] = useState("");
  const [error, setError] = useState("");

  function submit() {
    if (!name.trim()) {
      setError("Nombre requerido");
      return;
    }
    setError("");
    onAdd(name.trim(), Number(amount) || 0);
    setName("");
    setAmount("");
  }

  return (
    <div className="flex flex-col gap-1">
      <div className="flex gap-2">
        <input
          placeholder="Nombre"
          value={name}
          onChange={(e) => {
            setName(e.target.value);
            if (error) setError("");
          }}
        />
        <input placeholder="Saldo" type="number" value={amount} onChange={(e) => setAmount(e.target.value)} />
        <button className="primary" onClick={submit}>Agregar</button>
      </div>
      {error && <span className="text-sm text-red-600" role="alert">{error}</span>}
    </div>
  );
}

